programs.sol:
"""A token-boundary-sensitive long-vowel/phonetic-script feature.

The largest negative predictions are for katakana pieces beginning with a
long-vowel mark after an 'a' sound, especially pieces ending mid-character.
Completing that character gets a smaller negative prediction. Single Hangul
syllables have weaker phonetic rules, with a strong penalty for byte-split,
aspirated, open 'eo' syllables completed by a single byte. There are also
small Thai rules and a negative rule for repeated middle dots. Other tokens
are near zero. These are orthographic approximations, not exact activations.
"""
from functools import lru_cache
import codecs
import unicodedata
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=4096)
def vowel(character):
    if 'KATAKANA' not in unicodedata.name(character, ''):
        return '?'
    reading = anyascii(character).lower()
    return reading[-1] if reading and reading[-1] in 'aiueo' else '?'


@lru_cache(maxsize=32768)
def predict(b, preceding):
    decoder = codecs.getincrementaldecoder('utf8')('ignore')
    previous = decoder.decode(preceding)
    last = previous[-1:] or ' '
    sound = vowel(last)
    if last == 'ー':
        sound = vowel(previous[-2:-1] or ' ')
    text = decoder.decode(b)
    completion = bool(b and 128 <= b[0] < 192)

    if text.startswith('ー'):
        if b.endswith((b'\xe3\x82', b'\xe3\x83')):
            return dict(a=-3.5, i=-.72, u=-.82, e=.30, o=-.84).get(sound, -1.5)
        if text == 'ー':
            return dict(a=-1.5, i=.16, u=.60, e=.80, o=.10).get(sound, .2)
        if sound == 'a':
            return -1.8
        sonorant = anyascii(text[1:]).lower().startswith(('r', 'm', 'n'))
        if sonorant:
            return .05 if sound in 'iue' else -.02
        return dict(i=-.30, u=-.05, e=-.03, o=-.60).get(sound, -.2)

    if completion and last == 'ー' and len(text) == 1:
        if 'KATAKANA' in unicodedata.name(text, ''):
            return dict(a=-.85, o=-.35).get(sound, -.08)

    if len(text.strip()) == 1:
        character = text.strip()
        syllable = ord(character) - 0xAC00
        if 0 <= syllable < 11172:
            # Unicode Hangul syllables encode onset, vowel, and final consonant.
            onset = syllable // 588
            middle = syllable // 28 % 21
            closed = bool(syllable % 28)
            aspirated = onset in (14, 15, 16, 17)  # ch, k, t, p
            nasal = onset in (2, 6)               # n, m
            if completion:
                if middle == 4 and aspirated and not closed and len(b) == 1:
                    return -5.0  # a single byte completing an open eo syllable
                if middle == 4 and nasal and closed:
                    return -.8
                if middle == 18:                 # eu
                    return -.9 if aspirated and closed else -.4
                return -.35 if middle == 20 else -.25
            if middle == 4 and not closed:
                return -.38 if aspirated else -.2
            if middle == 18:
                if closed:
                    return -.24 if aspirated else .055
                return -.2
            if middle == 20:
                if nasal and not closed:
                    return -.62
                return -.2 if aspirated else -.035
            return -.005
        name = unicodedata.name(character, '')
        if 'THAI' in name:
            return -.43 if character == '์' else -.03

    if 'ー' in text:
        return -.098
    if any('KATAKANA' in unicodedata.name(c, '') for c in text):
        return -.215 if sound == 'a' else -.05
    if completion:
        return -.03
    if text == '··':
        return -.90
    return .002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ()
    current = prefix.token_bytes[-1]
    value = predict(current, b''.join(history))
    # Retain three tokens of byte context, resetting at document boundaries.
    return (document, (history + (current,))[-3:]), value

"""Approximate a signal for lexicalized bare-noun constructions.

Selected complements ('for use', 'of interest', 'at rest') receive large
negative values. WordNet supplies weaker fixed-expression and abstract-noun
rules. Geographic modifiers have the opposite sign; discourse formulas are
excluded. There are also light-verb and French/Spanish expression rules.
One adjective may intervene ('at increased risk'). Social 'of color' is
separated from literal color uses. Two previous tokens are remembered,
with memory reset at document boundaries. This is not a general parser.
"""
from functools import lru_cache
import wordnet

READS = ()


def words(s):
    return frozenset(s.split())


PREPOSITIONS = words('of in on at to for by into upon under from')
VERY_STRONG = {
    'for': words('sale use download purchase'),
    'at': words('rest risk stake play issue'),
    'in': words('question use need'),
    'into': words('view'),
    'under': words('construction'),
    'on': words('display'),
}
STRONG = {
    'of': words('''interest origin record symmetry concern manufacture
        study war parliament'''),
    'in': words('''place contact charge touch excess service demand
        motion office sync existence'''),
    'at': words('hand ease'),
    'on': words('appeal demand fire'),
    'to': words('death mind life'),
    'for': words('release review discussion consideration'),
    'under': words('investigation'),
    'from': words('rest'),
    'upon': words('receipt'),
    'into': words('contact'),
}
# Complements naming legal/social relationships, duties, or statuses.
RELATIONAL = words('''citizenship death marriage duty health staff service
    responsibility defense defence commerce state congress reference operation
    use stock type''')
MEASUREMENTS = words('length width height depth size age distance speed')
LINKING = {
    'in': words('accordance conjunction compliance connection relation comparison'),
    'by': words('default definition design law way reference'),
    'to': words('light blame health completion fruition'),
    'for': words('simplicity improvement inclusion delivery trial'),
    'into': words('position'),
}
STATES = words('mind memory nature practice progress error')
CONNECTIVES = words('''fact course example instance order case particular general
    conclusion addition contrast turn front time vivo vitro terms''')
DIRECTIONS = words('''north south east west northern southern eastern
    western central upper lower''')
QUALITATIVE = words('''importance significance use value note consequence
    merit relevance benefit''')
ABSTRACT = {'noun.act', 'noun.state', 'noun.attribute', 'noun.process'}


@lru_cache(maxsize=50000)
def response(previous, token):
    if not token or token[0] not in ' _-':
        return 0.0
    p = previous.strip(' _-/\n').lower()
    raw = token.strip(' _-/\n')
    w = raw.lower()
    if w in VERY_STRONG.get(p, ()):
        return -6.0
    if w in STRONG.get(p, ()):
        return -3.3
    if p == 'en':
        if w in {'place', 'question'}:
            return -5.0
        if w in {'ligne', 'línea', 'charge', 'cuenta', 'qualité'}:
            return -3.0
    if p == 'à' and w == 'jour':
        return -1.6
    if p in PREPOSITIONS:
        place_modifier = w in DIRECTIONS or (
            raw.istitle() and w in {'new', 'modern', 'royal'}
        )
        if place_modifier:
            return 1.4 if p == 'of' else 0.8
        if p == 'in' and w in {'early', 'rural', 'downtown'}:
            return 1.6
        if w in CONNECTIVES or w in {'it', 'this', 'that', 'all', 'one', 'other'}:
            return 0.0
        if w in LINKING.get(p, ()) or (p == 'in' and w in STATES):
            return -1.4
        if p in {'of', 'in'} and w in MEASUREMENTS:
            return -1.2
        if p == 'of' and w in QUALITATIVE:
            return -2.0
        if p == 'of' and w == 'birth':
            return -0.9
        pos = wordnet.parts_of_speech(w) if w.isalpha() else ()
        if 'noun' in pos:
            if p == 'of' and w in RELATIONAL:
                return -1.6
            if wordnet.parts_of_speech(p + ' ' + w):
                return -1.2
            if 'adjective' not in pos and p not in {'to', 'from'}:
                return -0.35 if wordnet.categories(w) & ABSTRACT else -0.1
    if (p in {'take', 'takes', 'taking', 'took', 'taken'}
            and w in {'place', 'effect', 'precedence'}):
        return -1.6
    if p in {'make', 'makes', 'making', 'made'} and w == 'use':
        return -2.0
    if p in {'give', 'gives', 'giving', 'gave', 'given'} and w == 'rise':
        return -3.0
    return 0.0


@lru_cache(maxsize=50000)
def predict(older, previous, token):
    value = response(previous, token)
    p = previous.strip(' _-/\n').lower()
    w = token.strip(' _-/\n').lower()
    before = older.strip(' _-/\n').lower()
    # Social 'people of color' is unlike literal uses of the color noun.
    if p == 'of' and w in {'color', 'colour'}:
        if (wordnet.is_a(before, 'person')
                or wordnet.is_a(before, 'social group')):
            return -3.3
    # A modifier can separate the preposition and its bare noun:
    # 'at increased risk', not 'an increased risk'.
    if (abs(value) < 0.4 and before in PREPOSITIONS
            and 'adjective' in wordnet.parts_of_speech(p)):
        value = 0.65 * response(older, token)
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        older, previous = '', ''
    else:
        _, older, previous = carry
    return (doc, previous, token), predict(older, previous, token)

"""A sparse lexical detector, with an isolated-token correction.

The main positive responses are particular Chinese action roots (chasing,
extracting, breathing, rushing), and applying/declaring with 申. Common
compounds have weaker, separately calibrated responses. Korean 추/충 and 신
also respond. A few spelling-completion rules cover project/trajectory
stems, j after accented vowels, Vietnamese trung and Korean 신고 (report).
Reform (改革) is assigned a negative response. These are lexical rules,
not a claim that every motion verb activates. Recent Japanese kana weakens
selected full-character responses.

At the beginning of a document, or while its initial token is simply
repeated, a separate surface-form rule usually gives a negative value.
"""
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
JAPANESE_SCALE = {'追': 0.63, '申': 0.72, '抽': 0.9,
                  '吸': 0.76, '沖': 0.67, '衝': 0.8, '伸': 0.83}

# Pursuit, rushing, extension and extraction; values are fitted strengths.
MOTION = {
    '追': 6.4, '追求': 0.7, '追赶': 2.0,
    '冲': 2.9, '沖': 2.8, '衝': 2.15,
    '冲刺': 3.8, '冲击': 2.2, '冲洗': 1.5,
    '抽': 3.0, '伸': 1.65, '拉': 0.4, '推': 0.4, '退': 0.4,
    '迎': 0.8, '充': 0.6, '补充': 0.9,
}
BREATHING = {
    '吸': 3.6, '吸收': 1.6, '吸引': 0.8, '呼吸': 0.9, '呼': 0.55,
}
APPLICATION = {
    '申': 7.0, '申请': 3.4, '申請': 2.9, '申报': 3.2, '申请人': 2.0,
    '声明': 1.1,
}
LEXICAL = {**MOTION, **BREATHING, **APPLICATION}


def isolated(s, b):
    """Surface shape of a token without a preceding distinct token."""
    t = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return 0.1
    if not t:
        if s == ' ':
            return -0.5
        return -0.38 if '\n' in s or '\r' in s else 0.15
    if any(c < 32 and c not in (9, 10, 13) for c in b):
        return -3.0
    if t.isascii() and t.isdigit():
        return -0.88
    if set(t) == {'·'}:
        return -1.4
    if t in ('I', 'i'):
        return -0.9 if s[0].isspace() else -1.8
    if not t.isascii():
        return -0.38 if '�' in t else -0.5
    v = -0.7 + 0.035 * min(len(t), 10)
    if s[0].isspace():
        v += 0.2
    if t.lower() in {'is', 'are', 'be', 'been', 'am', 'was', 'were'}:
        v += 0.55
    if t.lower() in {'it', 'he', 'she', 'we', 'they', 'you'}:
        v += 0.35
    if t.lower() in {'this', 'that', 'these', 'those'}:
        v += 0.24
    if t in {'import', 'from', 'package', '#include', '#!/'}:
        return -1.0
    if not t.isalpha():
        v = -0.4
        if t[0] in '-_#*':
            v -= 0.5
        elif t[0] in '([{<\'"`/':
            v -= 0.2
        if '\n' in s:
            v += 0.3
    return v


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b, True, 100, b'', '')
    _, first, repeated, kana_age, tail, previous = carry
    repeated = repeated and b == first
    kana_age = 0 if KANA.search(s) else kana_age + 1
    combined = tail + b
    text = s.strip()
    fragment = bool(b and 0x80 <= b[0] <= 0xBF)
    if fragment:
        decoded = combined.decode('utf-8', errors='ignore')
        if decoded and combined.endswith(decoded[-1].encode('utf-8')):
            text = decoded[-1]
    value = LEXICAL.get(text, 0.0)
    if text in {'追', '申', '抽', '吸', '冲', '沖', '衝', '伸'}:
        if fragment:
            value *= 1.35
        elif kana_age < 24:
            value *= JAPANESE_SCALE.get(text, 1.0)
    if text == '추':
        value = 3.7 if s.startswith(' ') else 2.6
    elif text == '충':
        value = 4.3
    elif text == '흡':
        value = 6.0
    elif text == '신':
        value = 1.05 if s.startswith(' ') else 0.65
    elif text == '改革':
        value = -1.5
    # Report/declaration in Korean, and a Vietnamese 'trung' completion.
    if text == '고' and previous.endswith('신'):
        value = 2.8
    if text == 'ung' and regex.search(r'(?:^|\W)[Tt]r$', previous):
        value = 2.0
    # Project abbreviations, trajectory stems, and accented-vowel + j.
    if text == 'j':
        if previous.lower().endswith('pr'):
            value = -2.4
        elif previous.endswith(('á', 'ú')):
            value = -1.4
    elif text == 'aj' and previous.lower().endswith('tr'):
        value = -2.6
    if repeated:
        value = isolated(s, b)
    carry = (doc, first, repeated, kana_age,
             combined[-6:], (previous + s)[-16:])
    return carry, float(value)

programs.haiku:
"""Layer 1 MLP down_proj component 5828.

Mostly silent. It responds to two things:
1. The first token of each document (or of a packed row). There the
   activation is negative, about -0.5: digits about -0.8, plain Latin words
   about -0.6, other text about -0.4; chat-template tokens are slightly
   positive. Later tokens are ~0.
2. Chinese verb morphemes, positive. Strongest on 申 / 申请 (apply) and
   追 (chase, 追诉); strong on 冲 / 沖 / 衝 / 冲刺 / 冲击 (rush, impact),
   抽 (draw, pump) and 吸 (suck); weaker on 攻 (attack), 争 / 竞争 (compete),
   推 (push), 伸 (stretch) and 吸引 (attract).
"""

READS = ()

TOP = {"申", "申请", "追"}
STRONG = {"冲", "沖", "衝", "冲刺", "冲击", "抽", "吸"}
WEAK = {"攻", "争", "爭", "竞争", "推", "伸", "吸引", "迎"}


def doc_start_value(tok):
    if tok.startswith("<|"):
        return 0.1
    if tok.strip().isdigit():
        return -0.8
    if tok.isascii() and tok.isalpha():
        return -0.6
    return -0.4


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[-1]
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, doc_start_value(tok)
    if tok in TOP:
        return carry, 5.0
    if tok in STRONG:
        return carry, 3.0
    if tok in WEAK:
        return carry, 1.0
    return carry, 0.0

programs.sol:
"""Spelling-centered steal/steel response, including split st-/ste- words.

Chinese stealing/steel characters and Cyrillic стал get related responses.
A few negative responses distinguish other st- spellings, 'but still',
forum post-count labels, and the abbreviation SPSS. All else is zero.
This is a spelling-based approximation, not a general semantic detector.
Only the immediately preceding token is remembered, within its document.
"""
import re
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word, prev = raw.strip().lower(), old.strip().lower()
    split = bool(raw and not raw[0].isspace() and prev in ('st', 'ste'))
    spelling = prev + word if split else word
    value = 0.0

    if spelling.startswith('steel') and not spelling.startswith('steelers'):
        value = 8.5 if split else (5.5 if raw[:1].isspace() else 4.0)
    elif spelling.startswith('stealth'):
        value = 2.5
    elif spelling.startswith('steal'):
        value = 8.0 if split else 6.0
    elif spelling.startswith('stole'):
        value = 6.0 if split else (3.0 if word == 'stolen' else 4.2)
    elif spelling == 'ste':
        value = 3.2 if raw[:1].isspace() or raw[:1].isupper() else 0.9
        if prev in ('back', 'beef') and not raw[:1].isspace():
            value = 16.0 if prev == 'back' else 7.0
    elif spelling == 'stee' and split:
        value = 8.0
    elif spelling.startswith(('steer', 'steep', 'stein', 'steen')):
        value = 2.5
    elif split and spelling.startswith(('stear', 'steu')):
        value = 4.5
    elif split and re.match(r'st(?:ave|ät|i[mn]|et[st]?$)', spelling):
        value = -6.8 if spelling == 'stave' else -3.0
    elif word in ('钢', '鋼', '抢', '搶', '偷'):
        value = 1.7 if word == '偷' else 6.0
    elif word in ('стал', 'стали'):
        value = 1.8
    elif word == 'theft':
        value = 1.4

    if raw == ':' and old.strip() in ('Posts', 'Views'):
        value = -4.7 if prev == 'posts' else -2.8
    elif word == 'still' and prev == 'but':
        value = -3.1
    elif raw == ',' and prev == 'still':
        value = -1.5
    elif word == 'ss' and prev == 'sp':
        value = -3.0
    elif not old and raw in ('st', 'St', 'Stan'):
        value = -3.5
    return (doc, raw), value

programs.haiku:
"""v4: steal/steel words (and Chinese steel 钢, steal/rob 偷 抢 搶), 'Ste' word
fragments of steel/steal-like words, and the colon after 'Posts' / 'Views' (negative)."""
READS = ()

STEAL = {"steal": 6.0, "steals": 6.0, "stealing": 5.5, "stolen": 3.5, "stole": 4.5,
         "steel": 5.5, "theft": 1.5}
STE_WORDS = {"steep": 2.0, "steeper": 2.5, "steer": 2.0, "steering": 2.0, "stein": 2.3}
STE_FRAGMENTS = {"ste": 2.5}
CJK = {"钢": 5.5, "抢": 6.5, "搶": 6.0, "偷": 1.5}
NEG_LABELS = {"Posts": -4.7, "Views": -2.8}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    word = tok.strip().lower()
    if tok in CJK:
        return carry, CJK[tok]
    if word in STEAL:
        return carry, STEAL[word]
    if word in STE_WORDS:
        return carry, STE_WORDS[word]
    if word in STE_FRAGMENTS:
        return carry, STE_FRAGMENTS[word]
    if tok == ":" and prev in NEG_LABELS:
        return carry, NEG_LABELS[prev]
    return carry, 0.0

programs.sol:
"""Approximate short e--b fragments, rather than a topic or whole-word meaning.

The response is script- and boundary-dependent. It is weakened on larger or
familiar English chunks, reversed on O+B and binary-prefix 0b, and briefly
persists into a continuing word. Repeated middle dots get a negative baseline.
"""
from functools import lru_cache
import math
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def pulse(s, prev, binary):
    t = s.strip().lower()
    z, before = anyascii(t).lower(), anyascii(prev).lower()
    joined = not s[:1].isspace()
    n = len(t)
    value = 0.0
    if regex.fullmatch(r'\p{Latin}+', t) and n <= 8:
        if 'eb' in t and zipf_frequency(t, 'en') < 4:
            if joined and t.startswith('eb') and n <= 3:
                value += 5.2
            elif t.endswith('b') or (joined and n <= 4):
                value += 7.0 / n
        if joined and t.startswith('b'):
            if n == 1:
                value -= 0.2
            if before.endswith('e') and n <= 3:
                strength = 6.8 if prev[-1:].lower() == 'e' else 1.5
                if before.endswith('ie'):
                    strength *= 0.2
                if s[0].isupper() and prev[-1:].islower():
                    strength *= 0.2
                word = prev.strip().lower()
                if len(word) >= 4 and zipf_frequency(word, 'en') > 3.8:
                    strength *= 0.2
                value += strength / math.sqrt(n)
            if before.endswith('o'):
                value -= 1.2 / math.sqrt(n)
            if binary and t == 'b':
                value -= 14.0
    elif regex.fullmatch(r'\p{Cyrillic}+', t):
        if 'еб' in t and t.endswith('б'):
            if n <= 3:
                value += 9.0 if joined else 3.6
            elif t[0] in 'аеиоуыэюяё':
                value += 5.7
            else:
                value += 3.2 / (n - 2) ** 2
        elif joined and z.startswith('b') and before.endswith('e'):
            value += 7.0 / math.sqrt(n)
    elif regex.fullmatch(r'[\p{Hiragana}\p{Katakana}ー]+', t):
        if t.endswith('れば'):
            value += 13.4 / n
        elif n == 1 and z.startswith('b'):
            value += 0.6
            if before.endswith('e') and regex.fullmatch(
                    r'[\p{Hiragana}\p{Katakana}]', prev[-1:]):
                value += 9.6
    if s and set(s) == {'·'}:
        value -= 0.74
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, earlier, old = '', '', 0.0
    else:
        prev, earlier, old = carry[1:]
    s = prefix.token_strings[-1]
    binary = prev == '0' and (not earlier or not earlier[-1].isalnum())
    current = pulse(s, prev, binary)
    continuing = s[:1].isalpha() and prev[-1:].isalpha()
    return (doc, s, prev, current), current + (0.23 * old if continuing else 0.0)

"""Approximate method-question and manner expressions.

English responses peak on 'to' in 'how to' and on personal subjects in
'how do/can I'. Heading position and capitalization adjust their strength.
Descriptive 'how it/that' is negative. Several translations, especially
Chinese 'how', are recognized too. Small rules cover 'way to' and 'never'.
Unmatched tokens get zero; the five-token memory resets between documents.
"""
READS = ()

# Function words immediately following English 'how'.
AFTER_HOW = {
    'can': 6.6, 'could': 3.1, 'would': 2.1,
    'do': 2.3, 'did': 1.6, 'does': 0.15,
    'should': 1.0, 'is': 1.3, 'are': 0.8, 'was': 0.9,
    'i': 1.4, 'we': 1.0, 'you': 0.45, 'one': 1.4,
    'it': -1.55, 'that': -1.3, 'they': -0.25,
    'about': -0.85, 'many': 0.18, 'best': 2.5,
}
PEOPLE = {'i', 'we', 'you', 'one'}


def english(history, raw, word, text):
    """Method-question grammar, not a general word-value lookup."""
    prev, prev2, prev3 = history[-1], history[-2], history[-3]
    if prev == 'how':
        if word == 'to':
            before = ''.join(raw[:-1])
            if before.endswith('user\n'):
                return 8.4
            if before.endswith('\n') or before.rstrip().endswith('#'):
                return 6.8
            return 6.4 if raw[-1].strip().startswith('H') else 5.15
        if word == 'can' and text.startswith('C'):
            return 4.5
        return AFTER_HOW.get(word, 0.0)
    if prev2 == 'how':
        if prev == 'do' and word in PEOPLE:
            if word == 'i':
                return 13.0 if text == 'I' else 6.5
            return 10.0
        if prev in {'can', 'would', 'should', 'could', 'did'} and word in PEOPLE:
            if prev == 'can':
                if word == 'i':
                    return 7.2 if text == 'I' else 3.3
                return 3.4 if word == 'you' else 6.0
            return {'would': 6.5, 'should': 3.2, 'could': 2.5, 'did': 0.7}[prev]
        if prev in {'does', 'would'} and word in {'it', 'this', 'that'}:
            return -1.5
        if prev in PEOPLE and word in {'can', 'would', 'could'}:
            return 1.2 if word == 'could' else 3.4
        if prev == 'it' and word == 'works':
            return -1.0
        if prev == 'to':
            if word in {'go', 'proceed', 'approach'}:
                return 2.7
            if word in {'do', 'make', 'get', 'set', 'change'}:
                return 1.4
            return 0.25 if word.isalpha() else 0.0
    if prev2 == 'where' and word == 'i':
        if prev in {'do', 'can'}:
            return 5.5 if prev == 'do' else 3.2
    if word == 'about' and prev in {'go', 'went'} and 'how' in history:
        return 5.5 if prev == 'go' else 3.3
    if prev3 == 'how' and prev2 in {'do', 'does', 'should'}:
        return 0.7 if word.isalpha() else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else [''] * 5
    raw = carry[2] if carry is not None and carry[0] == doc else [''] * 5
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower().strip('"\'/“”')
    if word == '-to':
        word = 'to'
    prev = history[-1]
    value = english(history, raw, word, text)

    # Chinese method interrogatives, including compounds and split spellings.
    if '怎么' in word or '怎麼' in word:
        value = 4.6 if word.startswith('是') else 6.6
        if word.endswith('样') or word.endswith('樣'):
            value = 4.7
