        value = 6.1
    elif '如何' in word:
        value = 3.8 if word.startswith('是') else 5.4
    elif word == '怎':
        value = 5.7
    elif word == '咋':
        value = 9.4
    elif word == '何' and prev == '如':
        value = 7.2
    elif word in {'麽', '麼'} and prev == '怎':
        value = 6.0
    elif word == '办' and prev in {'麽', '麼', '么'} and '怎' in history:
        value = 7.0
    elif word in {'才', '才能', '让', '讓'} and prev in {'怎样', '怎樣', '如何'}:
        value = 4.0
    elif word.endswith('どう'):
        value = 3.0
    elif prev.endswith('どう') and word in {'する', 'すれば'}:
        value = 4.0
    elif word == 'どのように':
        value = 3.6
    elif word == 'こう':
        value = 1.0
    elif word == 'cómo':
        value = 3.9 if text.startswith('C') else 1.1
    elif prev == 'cómo' and word in {'puedo', 'se'}:
        value = 3.6
    elif word in {'nasıl', '어떻게'}:
        value = 2.0
    elif word == 'как':
        value = 1.0 if text.startswith('К') else 0.4
    elif prev == 'как' and word in {'быть', 'можно', 'же'}:
        value = {'быть': 5.2, 'можно': 3.0, 'же': 4.0}[word]
    elif prev == 'wie' and word in {'man', 'sie', 'er'}:
        value = 3.5 if word == 'man' else 2.1
    elif word == 'never':
        value = 0.55
    elif word == 'to' and prev in {'way', 'ways', 'going', 'steps', 'what', 'where'}:
        value = 0.4

    return (doc, (history + [word])[-5:], (raw + [token])[-5:]), value

programs.haiku:
"""Fires on the words of a "how ..." question or phrase, at the point where the
verb of the action is about to come: the "to" of "how to", the "can" of "how can",
the subject after "how do" / "how would" ("I", "you", "we"), and the Chinese words
for "how" (如何, 怎么, 怎样, split or whole), including "办" after 怎么 ("what to do").
Zero everywhere else."""

READS = ()

# Chinese "how": whole words, and split pieces (怎 + 么, 如 + 何).
HOW_ZH_WHOLE = {"如何": 6.0, "怎么": 7.0, "怎麼": 7.0, "怎样": 7.0, "怎樣": 7.0, "どう": 3.0}
HOW_ZH_TAIL = {"何", "么", "麽", "麼", "样", "樣"}
HOW_ZH_HEAD = {"怎", "如"}
ZH_WHAT_TO_DO = {"办", "辦"}

# English: the word right after "how".
AFTER_HOW = {"to": 5.4, "can": 7.2, "do": 2.2, "would": 2.2}
# English: the subject after "how do" / "how can" / "how would".
AUX = {"do", "does", "did", "can", "could", "would", "should"}
AFTER_AUX = {"i": 11.0, "you": 10.0, "we": 9.0, "one": 8.0}


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    docs = prefix.document_ids
    t = len(words) - 1

    def word(k):  # the word k tokens back, within the same document
        i = t - k
        if i < 0 or docs[i] != docs[t]:
            return None
        return words[i]

    cur, prev, prev2 = word(0), word(1), word(2)
    if cur in HOW_ZH_WHOLE:
        value = HOW_ZH_WHOLE[cur]
    elif cur in HOW_ZH_TAIL and prev in HOW_ZH_HEAD:
        value = 7.0
    elif cur in ZH_WHAT_TO_DO and prev in {"么", "麽", "麼"}:
        value = 7.0
    elif prev == "how":
        value = AFTER_HOW.get(cur, 0.0)
    elif prev2 == "how" and prev in AUX:
        value = AFTER_AUX.get(cur, 0.0)
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""English 'one', especially in descriptions and the phrase 'one of'.

Responses are negative and strongest after 'is/was', 'as', and 'from'.
'This/it is one' is stronger than existential 'there is one'. Articles
and expressions such as 'no one' and 'at least one' weaken the response.
The following 'of' retains a context-dependent partitive response.
'Only', 'just', 'merely', and 'simply' give weaker related responses,
again strongest after forms of 'be'. Everything else is predicted zero.
This deliberately omits scattered non-English and background activity.
"""
READS = ()

COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am',
           "'s", '’s', "'re", '’re', "'m", '’m'}
DETERMINERS = {'the', 'a', 'an', 'any', 'each', 'some', 'which'}
ONE_MODIFIERS = {'no', 'least', 'first', 'last', 'another', 'number',
                 'exactly', 'only'}


def one_value(previous, before, partitive=False):
    """The preceding grammar; partitive=True means 'of' has now arrived."""
    if previous in COPULAS:
        if before == 'there':
            return -1.15
        if before == 'here':
            return -2.9
        if before in {'this', 'it'}:
            return -5.1
        return -4.8 if partitive else -4.2
    if previous == 'as':
        return -3.6
    if previous == 'from':
        return -1.7 if partitive else -2.9
    if previous in {'to', 'into', 'on'}:
        return -1.3 if partitive else -1.9
    if previous in {'of', 'by'}:
        return -1.2 if partitive else -1.55
    if previous in {'in', 'at', 'for', 'about'}:
        return -1.1 if partitive else -1.25
    if previous in ONE_MODIFIERS:
        return -0.5 if partitive else -0.12
    if previous in DETERMINERS:
        return -0.5
    if previous in {'just', 'also', 'not'}:
        if before in COPULAS:
            return -4.1 if partitive else -5.0
        return -2.1
    return -1.55 if partitive else -0.98


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0.0)
    _, last_token, before, older, last_value = carry
    previous = last_token.strip().lower()
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'one':
        if token == ' one':
            value = one_value(previous, before)
            if previous == 'just':
                value = -1.2 + 1.7 * last_value
        else:
            value = -0.55 if token.strip() != 'one' else -0.3
    elif word == 'of' and previous == 'one':
        value = (one_value(before, older, partitive=True)
                 if last_token == ' one' else last_value)
    elif token in {' only', ' just', ' merely', ' simply'}:
        if previous in COPULAS:
            value = -1.7 if word == 'only' else -2.0
            if before == 'there':
                value = -0.15
            elif before == 'this':
                value -= 0.9
            elif before == 'it':
                value -= 0.3
        elif previous in DETERMINERS or (previous == 'not' and word == 'only'):
            value = 0.0
        elif previous in {'in', 'of', 'as', 'than', 'to', 'on'}:
            value = -0.65 if word == 'only' else -0.9
        else:
            value = -0.25 if word == 'only' else -0.3
        if word == 'merely':
            value *= 0.75
        elif word == 'simply':
            value *= 0.35
    return (doc, token, previous, before, value), value

programs.haiku:
"""'one' used as a quantifier/pronoun, 'only'/'just' as focus words, and the 'of' in 'one of'.

The component goes negative on the word 'one' when it is a predicate or partitive ('is one of',
'are one of', 'as one of', 'from one of', 'by one'), strongest right after a linking verb, and on
'only' and 'just' after a linking verb ('is only', 'is just'). The 'of' that follows 'one' copies
the value of 'one' (it tracks the same thing). Existential 'there is one' and 'in one place' are weak."""
READS = ()
LINKING = {"is", "are", "was", "were", "be", "been", "being", "become", "becomes", "as", "s", "'s", "’s"}
STRONG_PREP = {"from", "to"}
PREPS = {"by", "on", "into", "of", "than", "within", "about", "at", "in", "with", "that", "this", "for", "and", ","}
NEGATED = {"no", "not", "least", "first", "second", "last", "another", "any", "only", "the", "a", "each", "every"}


def one_value(s):
    """Activation on the word 'one', given the tokens before it (s[-1] is 'one' itself)."""
    prev = s[-2].strip().lower() if len(s) > 1 else ""
    prev2 = s[-3].strip().lower() if len(s) > 2 else ""
    if prev in LINKING:
        return -1.0 if prev2 in ("there", "here") else -4.5
    if prev in STRONG_PREP:
        return -3.0
    if prev in PREPS:
        return -1.5
    if prev in NEGATED:
        return -0.3
    return -1.2


def step(carry, prefix, upstream):
    s = prefix.token_strings
    raw = s[-1]
    w = raw.strip().lower()
    prev = s[-2].strip().lower() if len(s) > 1 else ""
    if raw in (" one", " One", "One"):
        return None, one_value(s)
    if raw == "one":
        return None, -0.2
    if w == "of" and prev == "one":
        return None, one_value(s[:-1])
    if w in ("only", "just"):
        if prev in LINKING:
            return None, -2.0
        if prev in NEGATED or prev == "not":
            return None, -0.1
        return None, -0.4
    return None, 0.0

programs.sol:
"""A detector for ordinals and references to modern centuries.

Numeric ordinals have their largest response at twenty and twenty-one.
Century phrases rise sharply from older eras to the twentieth and twenty-first
centuries. Spelled-out, capitalized, hyphenated and Chinese/Japanese century
references are recognized too, as are year placeholders like 20XX. Calendar-date
ordinals are weaker. Secondary rules recognize language labels, biographical
headings, and a few social or civic compound expressions. These rules fit
recurring training patterns; other lexical responses are left near zero.
"""
import calendar
import math
import re
import inflect
import pycountry

READS = ()
_engine = inflect.engine()
ORDINALS = {
    _engine.number_to_words(_engine.ordinal(n)).replace('-', ' '): n
    for n in range(1, 101)
}
MONTHS = {s.lower() for s in calendar.month_name if s}
MONTHS.update(s.lower() for s in calendar.month_abbr if s)
DAYS = {s.lower() for s in calendar.day_name}
DIGITS = dict(zip('零一二三四五六七八九', range(10)))
DIGITS['〇'] = 0


def ordinal_strength(n):
    if 11 <= n <= 20:
        return 0.3 + 4.8 * math.exp(-(20 - n) / 2.6)
    if n == 21:
        return 4.1
    return 0.3


def century_strength(n):
    distance = max(-50, min(50, (19.4 - n) / 0.9))
    return -0.6 + 7.2 / (1 + math.exp(distance))


def chinese_number(s):
    if s.isdecimal():
        return int(s)
    if '十' in s:
        tens, units = s.split('十', 1)
        return 10 * DIGITS.get(tens, 1) + DIGITS.get(units, 0)
    if s and all(c in DIGITS for c in s):
        return int(''.join(str(DIGITS[c]) for c in s))
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (tail + token)[-120:]
    lower = text.lower()
    word = token.strip().lower()
    value = -0.002

    if word in {'th', 'st', 'nd', 'rd'}:
        match = re.search(r'(\d+)\s*(?:th|st|nd|rd)$', text)
        if match:
            n = int(match[1])
            value = ordinal_strength(n)
            before = text[:match.start()].lower()
            words = re.findall(r'[a-z]+', before)
            previous = words[-1] if words else ''
            if n in range(16, 22):
                if previous in {'the', 'early', 'late', 'mid'}:
                    value += 0.9
                elif previous in MONTHS or previous in DAYS:
                    value *= 0.55
            if token[:1].isspace():
                value *= 0.6
    elif token[-1:].isalpha():
        match = re.search(r'([a-z]+(?:-[a-z]+)?)$', lower)
        spelling = match[1].replace('-', ' ') if match else ''
        n = ORDINALS.get(spelling)
        if n is not None and 11 <= n <= 21:
            value = 0.2 + 0.35 * ordinal_strength(n)
            if n == 21:
                value = 3.8
            if word.replace('-', ' ') != spelling:
                value += 0.5
            if text[-len(spelling):][:1].isupper():
                value += 0.3

        if lower.endswith(('century', 'centuries')):
            match = re.search(
                r'(\d+\s*(?:st|nd|rd|th)|[a-z]+(?:-[a-z]+)?)'
                r'([ -]+)centur(?:y|ies)$',
                lower,
            )
            value = 0.15
            if match:
                spelling = match[1]
                digits = re.match(r'\d+', spelling)
                n = (int(digits[0]) if digits else
                     ORDINALS.get(spelling.replace('-', ' ')))
                if n is not None:
                    value = century_strength(n)
                    if not digits:
                        value -= 1.3
                    if '-' in match[2] and n >= 16:
                        value += 1.0 if n >= 20 else 0.5
                    if re.search(r'Centur(?:y|ies)$', text):
                        value += 1.0

        elif text.endswith(('世纪', '世紀')):
            match = re.search(
                r'([\d零〇一二三四五六七八九十]+)\s*世[纪紀]$', text
            )
            n = chinese_number(match[1]) if match else None
            value = 0.3
            if n is not None:
                value = min(9.0, 0.4 + 2 * century_strength(n))
            elif text.endswith(('本世纪', '本世紀')):
                value = 5.5
            elif text.endswith(('上世纪', '上世紀')):
                value = 1.7

    # A modern year template, or the compact century notation '21C'.
    if re.search(r'(?<!\d)(?:19|20)[xX]{2}$', text):
        value = 5.8 if re.search(r'20[xX]+$', text) else 3.5
    elif re.search(r'(?<!\d)(?:19|20|21)[cC]$', text):
        value = 3.2

    compound = compound_response(text, token)
    if compound is not None:
        value = compound
    return (doc, text), float(value)


def compound_response(text, token):
    """A few secondary responses to recognizable two-word expressions."""
    words = re.findall(r'[a-z]+', text.lower())
    if len(words) < 2 or not token[-1:].isascii() or not token[-1:].isalpha():
        return None
    previous, word = words[-2:]
    if word in {'language', 'languages'}:
        if previous in {'first', 'second', 'foreign'}:
            return 1.2
        language = pycountry.languages.get(name=previous.title())
        if language is not None:
            value = 2.0 if previous == 'english' else 1.4
            return value + (0.5 if '-' in token else 0)
    if word == 'life' and previous in {'early', 'personal'}:
        return -1.7 if previous == 'early' else -0.65
    if word == 'interest' and previous == 'public':
        return 3.5 if token.strip()[:1].isupper() else 2.5
    if word in {'science', 'sciences'} and previous == 'social':
        return 2.3
    if word in {'owned', 'controlled'} and previous == 'state':
        return 2.4
    return None

"""A local English requirements-and-completion approximation.

Recognize explicit personal tasks/goals and the words connecting them to actions:
"Your task is to", "We need to find", and similar constructions.  Responses are
negative, stronger for personal assignments and sentence-initial "We need".
Also recognize completion and a few fixed condition/request phrases.  Everything
else is near zero; this is phrase recognition, not general semantic inference.
"""
import re

READS = ()
GOALS = set('goal aim objective mission task job'.split())
ACTIONS = set('find prove show construct count calculate compute solve determine '
              'establish demonstrate'.split())
COPULAS = set('is are was be becomes become'.split())


def activation(before, token):
    word = token.strip().lower()
    raw = re.findall(r"[A-Za-z]+(?:['’][A-Za-z]+)?", before)
    words = [w.lower() for w in raw]
    last = words[-1] if words and re.search(r'[a-z]\s*$', before.lower()) else ''
    prior = words[-2] if len(words) > 1 else ''
    recent = set(words[-5:])
    personal = prior in ('your', 'our')
    if word in GOALS:
        if last in ('your', 'our'):
            if word in ('task', 'job'):
                return -6.4 if raw[-1] == 'Your' else -1.3
            return -2.7
        if last in ('the', 'main', 'primary', 'my'):
            return -0.2
    if word in COPULAS:
        if last in GOALS:
            return -2.5 if personal else -0.4
        if last in ('answer', 'question', 'problem', 'idea', 'key'):
            return -0.5
    if word == 'need' and last == 'we':
        return -1.1 if raw[-1] == 'We' else -0.4
    if word == 'to':
        if last == 'need':
            if prior == 'we':
                if raw[-2] == 'We':
                    return -3.6
                embedded = len(words) > 2 and words[-3] in (
                    'what', 'whether', 'that', 'as', 'do')
                return -0.7 if embedded else -2.0
            if prior == 'i':
                return -1.2
            if prior in ('the', 'no', 'not', "don't", "doesn't", 'never', 'any'):
                return 0.0
            if raw[-1] == 'Need' or prior in (
                    'so', 'now', 'thus', 'therefore', 'wait', 'hmm'):
                return -2.2
            return -0.5
        if last == 'suffices':
            return -3.0
        if last == 'required' and 'we' in recent:
            return -3.2
        if last in ('needs', 'needed', 'necessary', 'required'):
            return -0.15
        if last == 'like' and prior == 'would':
            return -2.5 if 'we' in recent else -0.4
        if last in COPULAS and recent.intersection(GOALS):
            assigned = len(words) > 2 and words[-2] in GOALS and words[-3] in (
                'your', 'our')
            return -4.6 if assigned else -1.0
        if last in ('is', 'are'):
            return -0.3
        if last in ('reduces', 'equivalent'):
            return -1.3
        if last in ('have', 'has', 'had', 'ought', 'asked', 'allowed', 'us'):
            return -0.2
    if word in ACTIONS and last == 'to':
        return -1.5 if recent.intersection(
            ('need', 'needs', 'required', 'suffices')) else -0.17
    if word == 'only' and last == 'and' and prior == 'if':
        return -3.7
    if word == 'long' and last == 'as':
        return -0.8
    if word in ('required', 'desired') and last == 'as':
        return -1.7
    if word == 'done' and last in (
            'are', 'were', 'is', "i'm", 'almost', "you're", "we're",
            'i’m', 'you’re', 'we’re'):
        if 'we' in recent:
            return -5.0
        if recent.intersection(('i', 'you', "i'm", "you're", "we're",
                                'i’m', 'you’re', 'we’re')):
            return -3.0
    if word == 'for' and last in ('look', 'looking', 'asked', 'asking', 'ask'):
        return -0.3
    if word == 'if' and last in ('see', 'check'):
        return -0.35
    if word == 'with' and last in ('faced', 'us'):
        return -1.4
    return 0.0015


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    return (document, (before + token)[-160:]), activation(before, token)

