READS = ()

SCALE = 0.5
NEED = {"need", "needs", "needed", "must", "required", "require", "requires"}
GOAL_HEAD = {"goal", "task", "aim", "objective", "job", "key", "challenge", "problem", "answer", "question"}
ACTION_VERBS = {"find", "solve", "compute", "construct", "show", "prove", "check", "determine", "calculate"}
NEG_WORDS = {"task", "goal", "prove", "desired", "challenge", "assume", "allowed", "solve", "compute",
             "construct", "find", "required", "important", "remaining", "welcome", "reduces", "equivalent"}
POS_WORDS = {"am", "'m", "hold", "able", "ready", "feel", "seems", "looks", "looking", "shows", "showing",
             "etc", "therefore", "hence", "these", "tried"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    w = toks[-1].strip().lower()
    p1 = toks[-2].strip().lower() if len(toks) > 1 else ""
    p2 = toks[-3].strip().lower() if len(toks) > 2 else ""
    if w == "to" and p1 in NEED:
        v = -0.9
    elif w == "to" and p1 in ("is", "are", "was") and p2 in GOAL_HEAD:
        v = -2.5
    elif w == "to" and p1 in ("is", "are", "was"):
        v = -0.6
    elif w in ("is", "are") and p1 in GOAL_HEAD:
        v = -0.7
    elif w in ACTION_VERBS and p1 == "to":
        v = -0.5
    elif w in NEED:
        v = -0.3
    elif w == "if" and p1 == "see":
        v = -1.0
    elif w in NEG_WORDS:
        v = -0.2
    elif w in POS_WORDS:
        v = 0.15
    else:
        v = 0.0
    return None, SCALE * v

"""Layer-1 MLP down_proj component 5838: a "coming into view / being present" detector.

Reads the token being written and predicts how strongly this component fires on it:
- the verb 出现 / 出現 ("to appear") in any form (出现了, 会出现, 出现在): strongest, about 6;
- 存在 ("to exist", incl. 不存在, 存在着): about 3;
- a short list of Chinese verbs of coming about, launching or establishing
  (发生, 产生, 推出, 成立, 呈现, 采用, 采取, 达到, 实现 ...): about 1;
- 场 / 場 / 台 / 班 / 错 right after 出, 登, 上 or 下 (出场, 登场, 上台, 下班, 出错): about 4.
Everything else, and the first token of each row, predicts 0.
"""

READS = ()

APPEAR = 6.0
EXIST = 3.3
OCCUR = {"发生", "發生", "产生", "產生", "推出", "出台", "成立", "呈现", "呈現",
         "采用", "采取", "採用", "採取", "达到", "達到", "实现", "實現"}
STAGE = {"场", "場", "台", "班", "错", "錯", "阵"}
LEAD = {"出", "登", "上", "下"}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    word = prefix.token_strings[-1].strip()
    if "出现" in word or "出現" in word:
        return carry, APPEAR
    if "存在" in word:
        return carry, EXIST
    if word in OCCUR:
        return carry, 1.0
    if word in STAGE and prefix.token_strings[-2].strip() in LEAD:
        return carry, 4.0
    return carry, 0.0

programs.sol:
"""A surface-syntax approximation to a quoted-symbol detector.

Opening quotes followed by punctuation are the main negative cue;
escapes and separator arguments strengthen this response. Closing-string
punctuation and JSON opening braces give small positive values. Hexadecimal
prefixes and the colon of a document-initial Title: heading are separate cues.
No full parser is attempted: recent token spelling supplies the quote-role hints.
"""
import re

READS = ()

# Groups are ordinary punctuation classes, not tokenizer IDs.
SYMBOLS = (
    ('/', -2.38),
    ('.', -2.30),
    (',', -1.31),
    (':;', -4.01),
    ('-', -2.03),
    ('@', -2.27),
    ('([', -1.48),
    (')]', -5.52),
    ('{}', -1.17),
    ('<>', -1.18),
    ('_', -1.69),
    ('$', -0.79),
    ('\\', -0.74),
    ('+*=^%&#|', -1.66),
    ('"\'`', -1.37),
)


def predict(token, previous, tail, position):
    if position == 1 and previous == 'Title' and token == ':':
        return -16.07
    if re.fullmatch(r'x[0-9a-fA-F]+', token):
        if previous == '0':
            return -3.71
        if previous.endswith('\\'):
            return -0.47
    if token == '{"':
        return 0.48

    match = re.match(r'''^([\s(\[=+!\\]*)(["'`])(.+)''', token)
    if match:
        before, quote, body = match.groups()
        ch = body[0]
        opening = bool(before.strip('\\'))
        opening |= previous.endswith(('(\\', '[\\', '{\\'))
        opening |= bool(re.search(r'\w\s*[=!]={1,2}$', tail))
        opening |= ch not in ',:;.)]}!?\n\r' and not ch.isalnum()

        # A preceding quote, a line ending, or statement terminators instead
        # suggest that this token closes a string.
        if previous.endswith(quote) or before in ('!', '\\', '\\\\'):
            opening = False
        if ch.isspace() or ch == quote or '\n' in token or '\r' in token:
            opening = False
        if before.strip() == '+' and ch in ')]':
            opening = False
        if quote == '`' and previous.endswith('\\'):
            opening = False
        if (not before and ch in '<>+*&|^'
                and not previous.endswith(('=', '(', '[', '{', ',', '\\'))):
            opening = False
        if ch in ')]};' and len(body) > 1 and body[1] != quote:
            opening = False

        if opening and not ch.isalnum():
            value = -0.68
            for marks, strength in SYMBOLS:
                if ch in marks:
                    value = strength
                    break
            if quote == '`':
                value += 0.31
            if '(' in before:
                value -= 0.36
            if previous.endswith('\\'):
                value -= 2.37
            delimiter = re.search(
                r'\b(?:split|join|Split|Join)(?:\([^\n]{0,50})?$', tail
            ) or previous.rstrip().endswith(('==', '===', '!=', '!=='))
            if delimiter:
                value -= 1.48
                if ch in ',:;':
                    value -= 1.80
            if previous.strip() == 'File' and ch == '/':
                value += 2.13  # A traceback's quoted filename.
            if re.match(r'\.+/', body):
                value += 1.89  # A relative path, not a punctuation delimiter.
            if body.startswith('//'):
                value -= 1.26
            if ch in '/)]' and previous.strip() in ('+', '+=', '<<'):
                value += 2.35
            return value
        if quote == '"' and ch.isalpha() and not before:
            return -0.31

    if re.match(r'''^["']:''', token):
        return 0.25
    if re.match(r'''^["'],''', token):
        return 0.17
    if re.match(r'''^["'][)\]}]''', token):
        return 0.14
    if token in ('"', "'"):
        return -0.09
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, tail, position)
    return (doc, token, (tail + token)[-100:], position + 1), value

"""A small, mixed lexical detector, strongest on formal mathematical theory.

Theory names are more negative than ordinary uses of 'theory'.  The rules
follow split spellings of theoretical/theorem and combinatorics, recognize
signal/image processing, and a few productive Latinate endings.  Two large
positive responses mark a fresh document's 'Title:' and Python 'def'.
Unrecognized tokens are left near zero; this is not a complete lexical model.
"""
import re

READS = ()

STRONG_THEORIES = set(
    'number graph group representation information game'.split()
)
OTHER_THEORIES = set('set measure matrix model approximation chaos learning decision '
                     'utility type reliability integration ergodic stability sieve '
                     'homology music queueing'.split())


def predict(before, token):
    s = token.lower().strip()
    if token == ':' and before == 'Title':
        return 8.28
    if token == 'def' and not before:
        return 4.02
    # Whitespace has no predicted contribution.
    if not s:
        return 0.0
    if s == 'theory':
        words = re.findall(r'[a-z]+', before.lower())
        head = words[-1] if words else ''
        if head in STRONG_THEORIES:
            return -8.2
        if head in OTHER_THEORIES:
            return -4.09
        return -0.71
    # Keep a short spelling window so a word can span several tokens.
    joined = before.lower() + token.lower()
    word = re.search(r'[^\W\d_]+$', joined)
    word = word.group() if word else ''
    formal = re.search(r'(number|graph|gauge|topos)[ -]the\w*$', joined)
    if formal and s in {'-the', 'oret', 'theoret', 'ic'}:
        if s == 'ic':
            return -10.79
        if s in {'oret', 'theoret'}:
            return -7.51
        return -5.2
    if 'theoretically' in s:
        return -1.55
    if 'theoretical' in s:
        return -2.2
    if s == 'theorem' or word.startswith('theorem'):
        return -0.43
    if re.search(r'(theor|théor|теор)', word) or word.startswith('teor'):
        return -1.78
    if s == 'the' and token == 'the' and before[-1:].isalpha():
        return -0.43
    if 'combinator' in word:
        return -6.7 if word.endswith('ics') else -1.5
    if s == 'ic' and word.endswith(('algebraic', 'toric', 'kinetic')):
        return -1.02
    if s == 'processing':
        if before.lower().endswith('signal'):
            return -4.01
        if before.lower().endswith('image'):
            return -1.37
    if token == 'um':
        return 2.28 if before.lower().endswith('e') else 0.0
    if token == 'ium':
        return 0.19
    if token == 'oid':
        return 0.38
    if token == 'ant' and before.lower().endswith('r'):
        return 0.3
    if token in {'ent', 'ents'} and before.lower().endswith('orb'):
        return 2.19
    if token in {'理論', '理论', '論', '论'}:
        return -0.67
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    tail = '' if token == '<|endoftext|>' else (before + token)[-120:]
    return (doc, tail), value

programs.haiku:
"""Program v2: the component's sign-flipping pieces are words of the theory family
('theory', 'theoretical', 'theorem'...) and 'combinatorial/combinatorics' (negative),
plus one strong positive case: the colon of a 'Title:' label right after end-of-text."""

READS = ()

END = "<|endoftext|>"


def current_word(prefix):
    """Lower-cased letters of the word ending at the newest token (pieces joined)."""
    letters = []
    for s in reversed(prefix.token_strings):
        core = s.lstrip(" ")
        if not core or not core.isalpha():
            break
        letters.append(core.lower())
        if s != core:  # token carried a leading space: the word starts here
            break
    return "".join(reversed(letters))


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    if len(strs) >= 3 and strs[-1] == ":" and strs[-2] == "Title" and strs[-3] == END:
        return None, 8.3
    word = current_word(prefix)
    if "combinator" in word:
        return None, -3.0
    if "theorem" in word:
        return None, -0.5
    if "theor" in word:
        return None, -1.5
    return None, 0.0

programs.sol:
"""Detect predicative noun phrases: 'is a', 'as an', 'become the', etc.

Articles naming what something is give the largest negative response.
Existential 'there is' and additive 'as well as' are exceptions. Smaller
responses mark descriptive modifiers, membership ('part of', 'one of'),
and appositive indefinite noun phrases. A few Romance/German and Chinese
copular article patterns are included. Positive exceptions are 'is the
case' and the colon in a document-opening 'Title:' header. This is only
a shallow grammar, not a complete sentence parser.
"""
from functools import lru_cache
import wordnet

READS = ()
COPULA = set("is are was were be been being am 'm 're ’m ’re 's ’s".split())
CHANGE = set("becomes become became becoming remains remain remained".split())
LABEL = set("considered deemed regarded".split())
SKIP = set("not also just still already really actually simply only even both "
           "therefore indeed certainly probably generally usually often "
           "sometimes always never essentially basically quite rather very "
           "somewhat almost virtually merely truly much more less now "
           "currently itself himself herself neither all".split())
PRONOUNS = set("it he she they we you i this these those".split())
OBJECTS = PRONOUNS | set("him her them me us".split())
FACTITIVE = set("make makes made making call calls called calling "
                "consider considered".split())
CLASS_NOUNS = set("part member type kind form example component subset "
                  "group variety category sort version instance".split())
DEGREE = set("very highly fully extremely particularly especially relatively "
             "quite rather fairly exceptionally truly".split())
EVALUATIVE = set("good bad great important valuable useful effective powerful "
                 "strong weak wonderful excellent beautiful interesting "
                 "significant essential vital remarkable suitable perfect "
                 "valid correct".split())
REFERENCE = set("same little few number following other many much".split())
FOREIGN_COPULA = set("est sont était être es son era ser siendo soy eres "
                     "è sono era essere é são era ist sind war sein als "
                     "comme como".split())
FOREIGN_ARTICLE = set("un une una uno um uma ein eine einen einem einer".split())

@lru_cache(maxsize=8192)
def adjective(word):
    return len(word) > 2 and 'adjective' in wordnet.parts_of_speech(word)


def governor(words):
    j = len(words)-1
    while j >= 0:
        if words[j] in SKIP or words[j].endswith('ly'):
            j -= 1
        elif j and words[j-1:j+1] in [['in','fact'], ['no','longer']]:
            j -= 2
        else:
            break
    if j < 0:
        return 0.0
    w = words[j]
    if w in {"'t", '’t'} and j and words[j-1] in {'isn','aren','wasn','weren'}:
        w = 'is'
    if w in {"isn't", "aren't", "wasn't", "weren't"}:
        w = 'is'
    skipped = j < len(words)-1
    if w in COPULA or w in CHANGE or w in LABEL:
        existential = 'there' in words[max(0,j-3):j]
        question = j and words[j-1] in {'here','what','where'}
        if existential or question:
            return 0.0
        if w in CHANGE or w in LABEL:
            return 1.35
        if j and not skipped and w in {'is','are','was','were'}:
            subject = words[j-1]
            if subject in PRONOUNS | {'that'}:
                return 1.2
            if len(subject) == 1 and subject.isalpha():
                return 0.8
        return 1.35 if skipped or w in {"'m", "'re", '’m', '’re'} else 1.0
    if w == 'as':
        if j and words[j-1] in {'such','well','same','far','soon','long'}:
            return 0.0
        return 0.95
    if w == 'like':
        return 0.7
    if w in PRONOUNS and j and words[j-1] in COPULA:
        return 1.35
    if w in OBJECTS and j and words[j-1] in FACTITIVE:
        return 1.8
    if j >= 2 and words[j-1] in {'a','an','the','this','that'}:
        if words[j-2] in FACTITIVE:
            return 1.8
    if w in {'represents','represent','represented','form','forms','formed'}:
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        words, modifier = [], 0.0
    else:
        _, words, modifier = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    strength = governor(words)
    value = 0.0
    new_modifier = 0.0
    if words and words[-1] in {'of','among'}:
        strength = max(strength, modifier)
    if token.strip() in {'a','an','the'} and token[:1].isspace():
        scale = 2.8 if word != 'the' else 0.88
        value = -scale * strength
        if not strength and word != 'the':
            pre = words[-1] if words else ''
            if pre in {',','or','nor','but','than','into','not'}:
                value = -0.65 if pre != 'not' else -2.7
            else:
                value = -0.08
        new_modifier = strength or (0.2 if word != 'the' else 0.0)
    elif word in FOREIGN_ARTICLE and words and words[-1] in FOREIGN_COPULA:
        value = -2.5 if words[-1] not in {'ist','sind','war','sein','als'} else -1.8
    elif (word.startswith(('是','为','為','作為','作为','成为','成為'))
          and word.endswith(('一个','一個','一种','一種','一位','一名'))):
        value = -2.5
    elif word in {'一个','一個','一种','一種','一位','一名'} and words:
        if words[-1].endswith(('是','为','為','作為','作为','成为','成為')):
            value = -3.0
    elif word == 'one' and strength:
        value = -1.45 * strength
        new_modifier = strength
    elif word == 'of' and words and words[-1] == 'one':
        value = -3.0 * modifier
        new_modifier = modifier * 1.25
    elif word == 'among' and strength:
        value = -strength
        new_modifier = strength
    elif word == 'of' and words and words[-1] in CLASS_NOUNS:
        value = -0.6 * modifier
    elif word in CLASS_NOUNS and (strength or modifier):
        value = -1.3 * max(strength, modifier)
        new_modifier = max(strength, modifier) * 0.7
    elif word in DEGREE:
        value = -0.35 - 0.5 * max(strength, modifier)
        new_modifier = max(strength, modifier) * 0.8
    elif word == 'case' and words and words[-1] == 'the' and modifier:
        value = 2.1 * modifier
    elif modifier and word not in REFERENCE and adjective(word):
        scale = 1.8 if word in EVALUATIVE | {'most','least','only'} else 1.0
        value = -scale * modifier
        new_modifier = modifier * 0.65
    elif strength and word in EVALUATIVE:
        value = -0.45 * strength
    # Conservative amplitudes limit errors from the shallow parsing rules.
    value *= 0.95
    if word == ':' and words == ['title']:
        value = 9.58
    words = (words + [word])[-10:]
    return (doc, words, new_modifier), value

"""Approximate document-opening pulses from readable token categories.

Whitespace, punctuation, writing system, source-header keywords and English
word classes determine the pulse's sign and size. It lasts through consecutive
copies of the opening token. After that, the prediction is zero, except for
the second token of an opening '12' or the empty-comment layout '//\n//'.
This omits lexical variation within groups and small, diffuse responses later
in a document.
"""
import unicodedata
import regex

READS = ()


def opening_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return 0.08
    if text and text.isspace():
        if '\r' in text and '\n' not in text:
            return -11.84
        if text == ' ':
            return 1.84
        if text.strip('\t') == '':
            return 2.07
        if text.startswith('\n'):
            return 1.8
        if text == '\xa0':
            return 1.7
        return 0.4
    if not word:
        return 0.0
    if word.startswith(('"""', "'''")):
        return 8.15  # Python docstring delimiter
    if word.startswith('/*'):
        return 6.3 if '\n' in text else 4.2
    if word.startswith('//'):
        return -14.67 if text == '//\n' else 2.5
    if word.startswith(('#!', '#include')):
        return 3.0
    if text == 'package':
        return 7.95  # module declaration
    if text in {'import', 'from'}:
        return 5.4  # module import
    if text == 'using':
        return 1.7
    if text in {'const', 'var', 'let'}:
        return 3.3
    if word.lower() == 'try':
        return 3.1
    if word.isdecimal():
        return -0.06
    c = word[0]
    if '\ufffd' in word:
        return 1.9  # an incomplete UTF-8 character
    if regex.match(r'\p{Script=Han}', c):
        return 1.54
    if regex.match(r'[\p{Script=Hiragana}\p{Script=Katakana}]', c):
        return 1.55
    if regex.match(r'\p{Script=Cyrillic}', c):
        return 0.98
    if regex.match(r'[\p{Script=Arabic}\p{Script=Hangul}]', c):
        return 2.1
    if regex.match(r'\p{Script=Thai}', c):
        return 1.7
    if not c.isalnum():
        if any(ch.isalnum() for ch in word):
            return 0.0
        if word == '**':
            return 8.55
        if len(word) >= 3 and set(word) == {'^'}:
            return -4.67
        if c in ',，':
            return 1.8
        if c in '.。':
            return 1.7 if '\n' in text else 1.05
        if c == '#':
            return 2.6
        if c == '“':
            return 4.65
        if c in '"「【':
            return 2.2
        if c == "'":
            return 0.85
        if c == '(':
            return -0.65 if text.startswith(' ') else 2.05
        if unicodedata.category(c) in ('Pe', 'Ps'):
            return 1.3
        if c == '*':
            return 1.8
        if c == ';':
            return 0.9
        if c == '=' and text.startswith(' '):
            return 1.0
        return 0.0
    if word.isalpha() and word.isascii():
        if word.lower() == 'we':
            return -4.3
        lower = word.lower()
        if lower in {'do', 'does', 'did'}:  # do-support / do-verb forms
            return -4.8 if word == 'Do' else -2.0
        if lower in {'are', 'were'}:  # plural forms of 'be'
            return -3.2 if c.isupper() else -1.4
        if lower in {'that', 'which'}:  # relative determiners
            return -2.8
        if lower in {'a', 'an'}:  # indefinite articles
            return 0.6
        if lower in {'this', 'these'}:  # proximal demonstratives
            return 0.7
        if not text.startswith(' ') or c.isupper():
            if lower in {'i', 'we', 'you', 'he', 'she', 'it', 'they'}:
                return -1.75
            return -0.45
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    identity = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, identity, token, True, 0)
    _, first_id, first, uniform, age = carry
    uniform = uniform and identity == first_id
    value = opening_value(token) if uniform else 0.0
    if age == 1 and first == '1' and token == '2':
        value = -8.435
    if age == 1 and first == '//\n' and token == '//':
        value = 4.32
    return (doc, first_id, first, uniform, age + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:5846 -- a "document-opener" detector.

The component is almost silent except at the first token of a document (position 0 of a
packed row, or the token right after <|endoftext|>). There, attention can see only the token
itself, so its activation is a fixed function of which token opens the document. Between
document starts it is small, diffuse and context-dependent, so this program predicts 0 there.

At a document start, the value is read off the opening token's kind:
  - file and comment-block openers (package, import, from, /*, /**, triple quotes, #!/): large +
  - code keywords and markup or comment markers (var, let, using, #include, #, //, <?): +
  - punctuation, symbols, line breaks, CJK and other non-Latin letters: moderate +
  - imperative or title-like English words (Add, Use, Welcome, Title): mild +
  - sentence-opening pronouns, auxiliaries and greetings (We, So, Do, I, You, It, That): -
  - lowercase word fragments: mild -
  - a line break glued to a comment marker (//\\n, #\\n) or a carriage return: strongly -
  - digits and everything else: 0
"""

READS = ()

BLOCK_OPENERS = {"package", "import", "from", "const", "namespace", "#!/", "/*", "/**"}
BLOCK_OPENERS |= {'"""', "'''", '"""\n', "'''\n", "/*\n", "/**\n", "/*\r\n", "/**\r\n"}
CODE_AND_MARKUP = {
    "var", "let", "use", "using", "void", "public", "private", "export", "extern",
    "#include", "#ifndef", "#if", "<?", "<script", "<div", "<", "//", "#", "##", "###", "**",
    "“", "【",
}
BREAKS = {"\r", "//\n", "#\n", "#\r\n", "//\r\n"}
CLAUSE_OPENERS = set(
    """I we We you You they They it It he He she She so So do Do let Let Hi Hello Hey No
    are Are that That which Which who Who what What All One As as Since Every There Will will
    While But Now Where Most Many Please""".split()
)
IMPERATIVE_OR_TITLE = set(
    """Add Adding Making Start Just Welcome Check Title Introduction Using Get Use Create Write
    Make Last Total News Two These Our More New Home Free Try Find Show Explore Preparing
    Translate Posted Recently""".split()
)


def activation_at_document_start(token: str) -> float:
    if token in BLOCK_OPENERS:
        return 6.0
    if token in CODE_AND_MARKUP:
        return 2.5
    if token in BREAKS:
        return -12.0
    word = token.strip()
    if not word:
        return 1.5  # bare whitespace or newline
    if not any(ch.isalnum() for ch in word):
        return 1.0  # punctuation and symbols
    if word in CLAUSE_OPENERS:
        return -2.5
    if word in IMPERATIVE_OR_TITLE:
        return 1.5
    if word.isdigit():
        return 0.0
    if any(ord(ch) > 0x2E80 for ch in word):
        return 1.5  # CJK and other wide scripts
    if not word.isascii():
        return 0.8  # letters of other scripts (Cyrillic, Greek, Arabic, Thai, Korean...)
    if token.isascii() and token.isalpha() and token.islower():
        return -0.5  # lowercase word fragment, no leading space
    return 0.0


def step(carry, prefix, upstream):
    opens_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not opens_document:
        return None, 0.0
    return None, activation_at_document_start(prefix.token_strings[-1])

