import re

READS = ()
MODULE_HEADERS = {
    'import', 'from', 'package', 'using', '#include', '#pragma', 'namespace',
}


def document_start(s):
    if s == '<!':                 # HTML declaration opener
        return 6.83
    if s == '//\n':               # Empty line comment
        return 7.96
    if s == 'int':                # Integer type keyword
        return 1.0
    if s in MODULE_HEADERS or s in ('//', '/*', '/**'):
        return -1.15
    if s == '<':
        return -1.50
