    if s.startswith('<|'):
        return -0.24
    if s.strip().lower() in ('some', 'few', 'many'):
        return 0.55
    if s.strip().lower() in ('a', 'an', 'the'):
        return -0.20
    if s and not s.strip('#'):
        return -0.14
    return -0.35 if s.isascii() else -0.25


