from functools import lru_cache
import cedict
import opencc

_TO_SIMPLIFIED = opencc.OpenCC("t2s")

@lru_cache(maxsize=8192)
def simplified(text):
    return _TO_SIMPLIFIED.convert(text)

PERSONAL_PRONOUNS = {
    "我", "你", "他", "她", "它", "我们", "你们", "他们", "她们", "它们",
    "本人", "咱们",
}

