def is_verb(word):
    return any(g.startswith("to ") for g in cedict.glosses(word))


READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, [], '', '', '', False)
    _, stack, previous, line, recent, after_end = carry
    token = prefix.token_strings[-1]
    word = simplified(token)
    first = not recent
    value = 0.0
    closed_call = False
    # Remember whether each opening delimiter belongs to a call or subscript.
    for ch in token:
        if ch in '([':
            call = bool(previous) and (
                (previous.isascii() and previous.isalnum())
                or previous in "_)]>$"
