    # began after the corresponding opening delimiter.
    empty_call = re.search(r"\(\)[)\]]*\.", token)
    quoted_access = re.search(r"['\"][)\]]+\.", token)
    if empty_call or quoted_access:
        value = 0.96
    if re.search(r'[)\]]->', token):
        value = 0.65
    if token == ' .' and re.fullmatch(r'[ \t]*(?:\d+[ \t]+)?', line):
        if '\n' in recent and not first:
            value = 0.78
    if token == '<|im_end|>':
        value = 0.44
        if '</tool_response>' in recent[-80:]:
            value = 0.12
        elif '</tool_call>' in recent[-80:]:
            value = -0.025
        if first:
            value = -0.487
    elif token == '<|im_start|>':
        value = -0.41 if after_end else (0.073 if not first else -0.41)
    elif token == '<think>':
        value = -0.215
    elif token == '</think>':
        value = 0.114
    elif token == '</tool_response>':
        value = -0.127
    elif word in ('仅', '仅仅'):
        value = -1.0
    elif '下来' in word or word.startswith('剩下'):
        value = -1.45
    elif word in ('的', '了') and not first:
        prev = simplified(prefix.token_strings[-2])
        if prev in PERSONAL_PRONOUNS:
            value = 0.12 if token == '的' else 0.58
        elif token == '的' and '所' in recent[-5:]:
