        elif token == '的':
            value = -0.3 if is_verb(prev) else -0.17
        else:
            value = -0.31 if is_verb(prev) else 0.0
    elif word.endswith('的') and len(word) <= 5:
        grammatical = word in ('中的', '上的', '下的', '过的')
        value = -0.32 if grammatical else -0.1
    elif token == ':' and recent == 'Title':
        value = -1.71
    if first and value == 0.0:
        if token.startswith('#'):
