"""Layer 1, MLP down-projection, component 5849: a method-chain dot detector.

In plain terms: the component switches on at the dot that continues a chain of calls or
lookups in source code, the `.` in `foo().bar`, `$("#id").html`, `x["k"].y`, where the next
token is a method or property name. It is weaker on `)).` and `]).` and on a bare `).` or
`].` inside code. It also rises at `<|im_end|>`, the end of an assistant turn. It goes
negative on Chinese particles that attach a modifier or complement to a noun or verb:
的 (most of all after a verb, as in 所获得的), 了, 下来, 接下来, 仅, 剩下.

Most of its variance is rare, large spikes that a short rule cannot reach. This program
explains a few percent to about 8% of the activation variance, depending on the sample.
"""

import re

READS = ()

# A closing `)`, `"` or `'` (or `]`) merged with a following `.` or `->`, as in `().`, `").`, `"].`.
CALL_DOT = re.compile(r"(\(\)|[\"']\)|[\"']\])(\.|->)")
# Any closer followed by `.` or `->`: `)).`, `]).`, `}).`.
CLOSER_DOT = re.compile(r".*[)\]](\.|->)")
# Punctuation that marks source code rather than prose.
CODE_MARKS = re.compile(r"[;{}=()\[\]<>_]|\.[A-Za-z]|->|::|\n|\t")
# Chinese words that attach a complement or modifier to a verb or noun.
CN_COMPLETIONS = {"下来", "下來", "接下来", "剩下", "剩下的", "仅", "僅", "仅仅", "下的", "中的", "上的"}


def in_code(prefix, window=25):
    """True when the last `window` tokens are dense with code punctuation."""
    text = "".join(prefix.token_strings[-window:])
    return len(CODE_MARKS.findall(text)) > 0.08 * max(1, len(text))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if CALL_DOT.fullmatch(tok):
        value = 0.8
    elif CLOSER_DOT.fullmatch(tok) and tok not in (").", "]."):
        value = 0.25
    elif tok == ")." and in_code(prefix):
        value = 0.25
    elif tok == "].":
        value = 0.2
    elif tok == " .":
        value = 0.1
    elif tok == "<|im_end|>":
        value = 0.23
    elif tok == "<think>":
        value = -0.2
    elif tok == "的":
        value = -0.22
    elif tok == "了":
        value = -0.27
    elif tok in CN_COMPLETIONS:
        value = -0.6
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A short-spelling contrast: San-like fragments are negative, some d/t + an
fragments are positive.  Long endings weaken the contrast.  The program
also recognizes saint/Santa forms and a few first-person English phrases.
It uses the current and previous token, resetting at document boundaries.
These are spelling rules, not a general semantic or pronunciation model.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    # Avoid false San matches from Chinese and hiragana transliterations.
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', text):
        return ''
    # Preserve Arabic's written long a, which anyascii normally omits.
    return anyascii(text.replace('ا', 'a').replace('آ', 'a')).lower()


def predict(token, previous):
    c, p = spelling(token), spelling(previous)
    w, q = c.strip(), p.strip()
    if q == 'let':
        if w == 'me':
            return -0.82
        if w in {"'s", 'us'}:
            return -0.41
    if q == 'i' and w == 'will':
        return -0.43
    if token.strip() in {'圣', '聖'}:  # Simplified/traditional "holy".
        return -4.65
    if token.strip() == '桑':  # Sang, also the mulberry character.
        return -3.42
    if token.isascii() and w == 'than':
        comparisons = {'more', 'less', 'rather', 'better', 'worse', 'other'}
        return 0.0 if q in comparisons or q.endswith('er') else 0.67
    if token.isascii() and w in {'dan', 'han', 'tan'}:
        return 0.51
    if c.startswith('aint') and p.endswith('s'):
        return -2.5
    if w in {'saint', 'saints'}:
        return -0.37 if token.strip()[0].isupper() else -1.83

    # San by itself, embedded in a short fragment, or in related words.
    if 'san' in w:
        before, tail = w.split('san', 1)
        if not tail:
            if before:
                return -3.26 / (1.0 + 0.5 * len(before))
            value = -5.85 if c == w else -4.18
            if regex.search(r'\p{Script=Katakana}|\p{Script=Hangul}', token):
                value *= 0.55
            return value
        if before not in {'', 'in'}:
            return 0.0
        if tail == 'ta':
            return -2.83
        if tail in {'t', 'ct', 'it', 'ity', 'e'}:
            return -1.86
        return -1.41 if tail == 's' else 0.0

    # Recognize an across the boundary, including a | n token splits.
    fragment, stem = c, p
    seam_script = regex.search(r'\p{Script=Greek}|\p{Script=Katakana}', token)
    roman_seam = token.lower() == 'n' and previous.isascii()
    if (seam_script or roman_seam) and c.startswith('n') and p.endswith('a'):
        fragment, stem = 'a' + c, p[:-1]
    if not c or c[0].isspace() or not fragment.startswith('an'):
        return 0.0
    tail = fragment[2:]
    if tail.startswith(('d', 'y')) or tail.endswith(('iya', 'iyu', 'ii', 'ie')):
        return 0.0
    closed = bool(tail and tail[0] not in 'aeiou')
    scale = 0.4 if len(tail) > 2 else 1.0
    if regex.search(r'\p{Script=Thai}', token):
        scale *= 0.6
    if stem.endswith('s'):
        value = -1.89 if closed else -4.75
    elif stem.endswith('z'):
        value = -1.40 if closed else -1.89
        if regex.search(r'\p{Script=Cyrillic}', token):
            scale *= 1.5
    elif stem.endswith(('x', 'sh', 'ch', 'zh')):
        value = -0.33 if closed else -1.15
    elif stem.endswith(('st', 'sk')):
        return 0.0
    elif stem.endswith(('ct', 'lt', 'th')):
        value = 1.04 if closed else 1.58
    elif stem.endswith('d'):
        value = 0.34 if closed else 1.23
    elif stem.endswith('t'):
        value = 0.13 if closed else 0.71
    elif stem.endswith(('r', 'h')):
        value = 0.03 if closed else 0.36
    else:
        return 0.0
    return value * scale


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), predict(token, previous)

