"""Approximate a sparse local spelling signal, not a semantic category.

Short w-to-l spellings get negative values; w-to-t spellings get positive
values. Token-boundary splits usually strengthen the response. Frequent
whole English words and common adverbs ending in -ly are largely exempt.
Separate negative rules recognize what/how about and what if/of. A few
opening-format rules handle initial carriage returns, comments and Title:.
The magnitudes are approximate; multilingual and other context effects are
not modeled. State resets between documents.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def spelling(token, preceding_word):
    # Spaces separate words; punctuation such as a hyphen need not do so.
    joined = not token[:1].isspace()
    letters = re.sub(r'^[^A-Za-z]+', '', token).lower()
    before = preceding_word.lower() if joined else ''
    if not letters:
        return 0.0
    if (len(before) > 2 and before != 'how' and not before.endswith('row')
            and zipf_frequency(before, 'en') >= 4.9):
        before = ''
    if (letters == 'ly' and len(before) > 2
            and zipf_frequency(before, 'en') > 4.0):
        return 0.0
    # Only the most recent w matters, and only short letter sequences after it.
    own_w = letters.rfind('w')
    if own_w >= 0:
        tail = letters[own_w + 1:]
        split = False
        if zipf_frequency(letters, 'en') >= 4.8:
            return 0.0
    elif ('w' in before and 'www' not in before
          and (token[:1].isascii() and token[:1].isalpha()
               or token.startswith('-'))):
        old_tail = before[before.rfind('w') + 1:]
        tail = old_tail + letters
        split = True
    else:
        return 0.0
    match = re.match(r'(al)(t)(.*)', tail)
    if match is None:
        match = re.match(r'([aeiouyhrgs]{0,4})([lt])(.*)', tail)
    if not match:
        return 0.0
    gap, consonant, suffix = match.groups()
    if split and len(gap) < len(old_tail):
        return 0.0
    if consonant == 't' and not split:
        if own_w > 0 or zipf_frequency(letters, 'en') >= 4.5:
            return 0.0
    if consonant == 'l':
        if split and not gap:
            if suffix in ('', 's', 'y', 'ey'):
                return -7.5
            if suffix in ('ing', 'ings', 'et', 'ett', 'en', 'ers'):
                return -6.0
            if token.isupper() and len(before) <= 3:
                return -11.0
            return -2.8
        if split:
            return -4.0 if gap == 'ai' else -1.2
        strength = 3.0 if token[:1].isspace() else 5.0
        if gap:
            strength = 0.6
        if suffix:
            strength *= 0.65 if suffix in ('ing', 's', 'er') else 0.3
        return -strength
