    return positive(gap, suffix, split, token)


def positive(gap, suffix, split, token):
    if gap not in ('', 'i', 'hi', 'hea', 'al',
                   'ri', 'res', 'righ', 'a', 'ar'):
        return 0.0
    if split:
        strength = 6.8 if gap == 'i' else 2.4
        if gap == 'hi':
            strength = 4.5
        if gap.endswith('al'):
            strength = 3.0
        if gap == 'hea':
            strength = 4.3
    else:
        strength = 3.6 if gap == 'i' else 1.7
        if gap.endswith('al'):
            strength = 2.8
        if gap == 'hi':
            strength = 2.4
        if not token[:1].isspace() and gap in ('i', 'hi', 'hea', 'al'):
            strength *= 1.7
    if suffix.startswith('t'):
        strength += 3.5 if gap == 'i' else 0.0
        suffix = suffix[1:]
    if len(suffix) > 2:
        strength *= 0.1
    elif suffix and suffix != 's':
        strength *= 0.4
    return strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, word, position, opening_returns = '', '', 0, True
    else:
        _, previous, word, position, opening_returns = carry
    token = prefix.token_strings[-1]
    p = previous.lower().strip(' \t\r\n\"\'“”‘’')
    if opening_returns and token == '\r':
        value = -3.86
    elif position == 0 and token == '//\n':
        value = -6.168
    elif position == 0 and token == '#':
        value = -0.955
    elif position == 1 and previous == 'Title' and token == ':':
        value = 10.085
    elif token.lower() == ' about' and p in ('what', 'how'):
        value = -12.3
    elif token.lower() in (' if', ' of') and p == 'what':
        value = -6.4
    else:
        value = spelling(token, word)
    # Keep just the trailing word, not a growing copy of the document.
    end = re.search(r'[A-Za-z]+$', token)
    if end:
        word = ((word if end.start() == 0 else '') + end.group())[-24:]
    else:
        word = ''
    return (document, token, word, position + 1,
            opening_returns and token == '\r'), float(value)

"""Approximate local counting, ordering, and correctness expressions.

Numbered Chinese installments and action counts are mostly negative; counted
months, branching/variety words, and qualified choices are positive. Correctness
words have separate negative rules. A coarse spelling/spacing rule handles the
first token of each document. Unmatched tokens return zero; lexical background
and longer-context effects are deliberately omitted.
"""
import inflect

READS = ()
_numbers = inflect.engine()
QUANTIFIERS = {_numbers.number_to_words(i) for i in range(1, 21)}
QUANTIFIERS |= {'many', 'few', 'several', 'all', 'multiple'}
PRONOUNS = {'I', 'We', 'He', 'She', 'They', 'It', 'You'}
STROKES = set('刀枪槍棍箭笔筆')
SEQUENCES = {'步', '歩', '遍', '波', '站', '格', '码', '碼'}
SIDES_ROUNDS = set('边邊圈轮輪')

# Responses when a number immediately introduces the unit.
COUNTERS = (
    (set('集页頁题題'), -3.78),       # episodes, pages, questions
    ({'章'}, -0.95),                  # chapters
    ({'环', '環'}, -3.5),             # rings
    (SEQUENCES, -2.31),               # steps, repetitions, waves, stations
    (STROKES, -2.41),                 # weapon/writing strokes
    ({'对', '對'}, -1.19),            # pairs
    (SIDES_ROUNDS, -1.03),
    ({'半'}, -2.02),                  # halves
    ({'切'}, -0.99),                  # everything, in 一切
    ({'刻'}, -0.94),                  # moments
    ({'天', '岁', '歲'}, -0.71),      # days and years of age
    ({'月', '时', '時', '時間', '시간'}, 0.51),  # months/hours
    ({'项', '項', '多'}, 0.76),       # items, or 'more than'
    ({'つ'}, -1.26),                  # Japanese object counter
    ({'叉'}, 2.91),                   # branching, as in binary trees
    ({'様'}, 2.86),                   # varieties/modes
    ({'脸', '臉', '肚子', '腔', '桌子', '曲'}, 2.21),  # counted nouns
    (set('哥姐弟妹'), 2.96),           # sibling order
)


def response(token, previous, first):
    text, prev = token.strip(), previous.strip()
    if first:
        if text.startswith('#') and text[1:].isalpha():
            return 0.81  # preprocessor directives, not heading hashes
        if text in {'package', 'using', 'namespace', 'def', 'function'}:
            return 0.82
        if text in PRONOUNS:
            return 0.65
        if text.isnumeric():
            return -0.2
        if text.startswith('#'):
            return -0.46
        if token[:1].isspace():
            return -0.09
        if text and text[0].isascii() and text[0].isupper():
            return 0.45
        return 0.09 if text.isascii() and text.isalpha() else -0.05

    if text == 'up' and prev.lower() in {'first', 'next'}:
        return -6.12
    if text.lower() in {'choice', 'choices'}:
        if prev.lower() == 'first':
            return 2.09
        if prev.isnumeric() or prev.lower() in QUANTIFIERS:
            return 1.46
        if prev.lower() in {'best', 'top', 'good', 'great', 'only', 'each'}:
            return 0.59
    if text == 'Ratings' and prev.isnumeric():
        return -0.83
    if text in {'的', '了'} and prev in {'对', '對', '正确', '正確'}:
        return -3.31 if text == '了' else -1.72  # 'correct' constructions
    if text in {'错', '錯'}:
        return -2.01  # wrong
    if text.endswith(('不错', '不錯', '没错', '沒錯')):
        return -2.38  # not bad / not wrong
    if text in {'不错的', '不錯的'}:
        return -0.73
    if text in {'不对', '不對'}:
        return -1.6
    if text == '棒':
        return -4.84 if prev.endswith('最') else -1.0  # great / greatest
    if text in {'机会', '機會', '选项', '選項'}:
        return 0.5  # opportunities and options

    if text in {'边', '邊'} and prev.endswith(('这', '這', '那', '哪')):
        return -1.92  # this/that/which side
    counted = bool(prev) and (prev[-1].isnumeric() or prev[-1] in '两兩几幾首')
    unit = text
    if text == '一页':
        return -0.7
    # Selected single-token 'one unit' compounds.
    if text.startswith('一') and text[1:] in (
        SEQUENCES | STROKES | SIDES_ROUNDS | {'半', '切', '刻'}
    ):
        unit, counted = text[1:], True
    if counted:
        for units, value in COUNTERS:
            if unit in units:
                return value
    if text == '様' and prev.endswith('多'):
        return 2.86  # diversity
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    return (doc, token), response(token, previous, first)

