"""Approximate an orthographic L response, without a word lookup table.

Fold accents and count Cyrillic el, Greek lambda and Arabic lam as L.
Isolated L pieces respond most strongly; longer L-initial pieces use case,
L density and token boundaries. Alphabetic fragments following L pieces
retain activity, especially short ASCII-vowel starts. Document beginnings
have separate calibration. Word-specific exceptions are not reproduced.
"""
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=32768)
def spelling(token):
    text = unicodedata.normalize('NFKD', token)
    text = text.replace('ł', 'l').replace('Ł', 'L')
    text = ''.join(c for c in text if not unicodedata.combining(c))
    letters = ''.join(c for c in text if c.isalpha()).lower()
    letters = letters.translate(str.maketrans({'л': 'l', 'λ': 'l', 'ل': 'l'}))
    capital = bool(letters) and next(c for c in text if c.isalpha()).isupper()
    ascii_letters = all(ord(c) < 128 for c in letters)
    return letters, text.isalpha(), bool(text[:1].isspace()), capital, ascii_letters


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    letters, alphabetic, spaced, capital, ascii_letters = spelling(token)
    state = (doc, position, letters)

    density = letters.count('l') / max(1, len(letters))
    vowel = letters[:1] in 'aeiouy' and bool(letters)
    if not letters.startswith('l'):
        if position == 0:
            if density > 0.118:
                value = 0.625
            elif spaced:
                value = 0.030
            else:
                value = 0.145 if len(letters) <= 3 else 0.339
        elif previous.startswith('l'):
            if len(previous) == 1:
                if not alphabetic:
                    value = 0.098
                elif len(letters) > 2:
                    value = 0.473
                elif vowel:
                    value = 0.925
                else:
                    value = 0.309 if ascii_letters else 0.727
            elif not alphabetic:
                value = 0.006
            else:
                value = 0.240 if previous[-1:] in 'aeiouy' else 0.038
        elif len(letters) <= 1:
            value = 0.001
        elif not previous.endswith('l') or not alphabetic:
            value = -0.006
        elif not vowel:
            value = -0.040 if ascii_letters else 0.105
        else:
            value = 0.157 if len(previous) <= 3 else 0.013
    elif len(letters) == 1:
        if not alphabetic:
            value = 0.791
        else:
            value = 0.875 if not previous else 0.173
    elif position <= 2:
        value = 0.607
    elif not alphabetic:
        if density <= 0.207:
            value = 0.133
        elif not capital:
            value = 0.190
        else:
            value = 0.540 if density > 0.414 else 0.242
    elif not previous:
        value = 0.494 if density > 0.414 else 0.220
    elif 'l' in previous:
        value = 0.256
    else:
        value = -0.114 if previous[-1:] in 'aeiouy' else 0.009
    return state, value

"""Demonstratives, chiefly this/these; English code's `this` is weaker.

Training examples chiefly pointed to proximal rather than distal deixis.
Most positive predictions are for this/these and selected foreign forms. A
split demonstrative gets an extra boost.  'The following', 'the current',
and a few possibility adverbs are secondary triggers.  Other tokens predict
zero; this is not a general semantic classifier for all referring expressions.
"""
import re

READS = ()

# Demonstrative forms (mainly proximal), plus the Italian stem quest-.
DEMONSTRATIVES = {}
for forms, strength in (
    ('dies diese dieser diesen diesem dieses', 1.2),
    ('ce cette ceci cela', 1.15),
    ('cet', 1.8),
    ('ces', 1.35),
    ('este esse essa isto', 1.15),
    ('esta estas estos', 1.7),
    ('esto', 1.05),
    ('isso', 0.6),
    ('estes esses essas', 1.6),
    ('quest', 0.9),
    ('questo', 1.2),
    ('questa queste questi', 1.5),
    ('ciò', 0.65),
    ('этот эти этого этому этих этим', 0.95),
    ('эта этой', 1.2),
    ('этом', 0.7),
    ('это', 0.5),
    ('denne dette', 1.15),
    ('detta', 0.7),
    ('acest aceasta acesta acestea aceste acesti acești', 0.7),
    ('deze', 1.1),
    ('bu', 0.7),
    ('هذا هذه', 0.75),
    ('이', 0.8),
    ('この', 0.33),
    ('此', 0.85),
    ('这些 這些 这个 這個 这种 這種 该', 0.32),
    ('这 這', -0.2),
    ('以下', 1.7),
):
    DEMONSTRATIVES.update(dict.fromkeys(forms.split(), strength))

# Portuguese contractions: of/in + this or that-near-the-listener.
CONTRACTED = {
    pre + stem + ending
    for pre in ('d', 'n')
    for stem in ('est', 'ess')
    for ending in ('e', 'a', 'es', 'as')
}
POSSIBILITY = {'perhaps': 0.49, 'possibly': 0.56, 'potentially': 1.45}


def unaccent_demonstrative(word):
    # Older Spanish spells these words with an initial accented e.
    return 'e' + word[1:] if word.startswith('ést') else word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
        first = True
    else:
        _, previous, tail = carry
        first = False
    token = prefix.token_strings[-1]
    word = unaccent_demonstrative(token.strip().lower())
    prev = previous.strip().lower()
    value = DEMONSTRATIVES.get(word, 0.0)
    # Latin/Cyrillic syllables inside another word are not demonstratives.
    spaced = token[:1].isspace()
    if value and re.match(r'[a-zа-я]', word):
        if token.strip().isupper():
            value = 0.0
        elif not spaced:
            value = 0.0 if tail else value * 0.5
    if word == '이' and not spaced:
        value = 0.13
    if word in CONTRACTED and spaced:
        value = 1.5

    if word == 'this':
        if '\t' in token:
            value = -0.3
        elif token == 'this':
            value = 0.15
        elif token == 'This':
            value = 0.42
        elif token.strip() == 'This':
            value = 0.55
        elif token.strip() == 'THIS':
            value = 0.85
        else:
            value = 0.67
            if prev in {'in', 'of'}:
                value = 0.82
                if previous.strip() == 'In':
                    value = 0.95
            elif prev in {'do', 'does', 'did', 'will', 'would', 'can', 'like'}:
                value = 0.3
            elif prev in {'is', 'was', 'make'}:
                value = 0.52
            elif prev in {'use', 'using', 'by', 'because'}:
                value = 0.82
        if (previous.isspace() and '\n' not in previous
                and len(previous) > 1):
            value = -0.15
        if prev in {'=', 'return', 'new', 'throw', '=>'}:
            value = -0.08
        if first:
            value = -0.75
    elif word == 'these':
        value = 0.9 if token.startswith(' ') else 0.8
    elif word == 'current':
        value = 0.35 if prev == 'the' else 0.0
    elif word == '-ci' and tail.lower() in {'celui', 'celle', 'ceux', 'celles'}:
        value = 1.05
    elif token == ' Dit':
        value = 1.0
    elif word == 'following':
        value = 0.67 if prev == 'the' else -0.05
    elif word in POSSIBILITY:
        value = POSSIBILITY[word]
        if not token.startswith(' '):
            value *= 0.7
    elif word == 'это' and token.strip()[0].isupper():
        value = 0.8

    # A suffix completing e.g. ess+as, quest+e, or Э+та.
    joined = tail + token
    match = re.search(r'[^\W\d_]+$', joined)
    new_tail = match.group(0)[-30:] if match else ''
    whole = unaccent_demonstrative(new_tail.lower())
    if (tail and token and token[0].isalpha()
            and whole != word):
        if (whole in CONTRACTED or (whole in DEMONSTRATIVES
                and whole.startswith(('est', 'ess', 'ist', 'quest', 'эт',
                                      'acest', 'deze', 'dies', 'ces')))):
            value = max(value, 2.0)
    return (doc, token, new_tail), value

"""Speech and explanation, including the grammatical links to their content.

Explaining and telling are strong negative signals; other communication and
comprehension verbs are weaker. Distinguish requests and reports by a speaker
from impersonal explanations. Join decoded word fragments and reset by document.
Small positive exceptions cover nominal understanding and quantity/state links.
Weights are rounded training means for these named classes, not token IDs.
"""
import re
import regex
from functools import lru_cache
import wordnet
import cedict

READS = ()

FAMILIES = {
    'explain': {'explain'},
    'explanation': {'explanation'},
    'describe': {'describe'},
    'mention': {'mention'},
    'tell': {'tell'},
    'speak': {'speak', 'talk'},
    'ask': {'ask'},
    'say': {'say'},
    'discuss': {'discuss', 'summarize', 'repeat'},
    'understand': {'understand', 'comprehend', 'learn'},
    'read': {'read'},
    'write': {'write'},
    'check': {'check', 'verify'},
    'teach': {'teach'},
    'hear': {'hear', 'recall'},
    'share': {'share', 'suggest'},
    'communicate': {'communicate', 'inform', 'notify', 'instruct',
                    'announce', 'introduce'},
    'speech_noun': {'description', 'discussion', 'summary', 'overview',
                    'opinion', 'instruction'},
}
VALUES = {
    'explain': -2.26, 'speaker_explain': -4.47,
    'request_explain': -4.62, 'unspaced_explain': -6.14,
    'past_explain': -1.68, 'explanation': -0.72,
    'explanation_of': -2.23, 'explain_that': -1.77,
    'tell': -1.1, 'request_tell': -1.78,
    'link_object': -1.04, 'request_object': -2.01,
    'say': -0.26, 'saying': -0.57,
    'said': -0.29, 'speaker_say': -1.42,
    'speaker_that': -2.02, 'speak': -0.63,
    'ask': -0.91, 'past': -0.39,
    'describe': -0.64, 'mention': -1.37,
    'discuss': -0.59, 'speech_noun': -0.14,
    'link_of': -0.98, 'point_out': -1.4,
    'link_that': -0.75, 'speech_about': -1.06,
    'speech_to': -0.35, 'link_article': -0.23,
    'about': -0.11, 'understand': -0.48,
    'understanding': 0.49, 'learning': -0.1,
    'knowledge_of': -0.45, 'think': -0.15,
    'deliberate': -1.26, 'teach': -0.82,
    'hear': -0.39, 'read': -0.55,
    'write': -0.11, 'share': -0.32,
    'check': -0.2, 'communicate': -0.27,
    'foreign_explain': -2.94, 'foreign_speech': -0.94,
    'han_speech': -0.3, 'state': -0.65,
    'report_state': -2.29, 'state_noun': 0.08,
    'political_state': -0.08, 'state_of': 0.42,
    'total_of': 0.99,
}
SPEAKERS = {'speaker', 'person', 'narrator', 'player'}
OBJECTS = {'me', 'you', 'us', 'him', 'her', 'them'}
SPEECH = {'tell', 'request_tell', 'speaker_say', 'ask', 'teach', 'explain',
          'request_explain', 'unspaced_explain',
              'speaker_explain', 'past_explain', 'say', 'saying', 'said', 'speak',
              'mention', 'discuss', 'state', 'report_state', 'past', 'write', 'hear'}

@lru_cache(maxsize=30000)
def family(word):
    roots = set(wordnet.base_forms(word))
    for name, members in FAMILIES.items():
        if roots & members:
            return name
    # Explanation and speech stems in Russian, German and Romance languages.
    if not roots and re.match(r'(объясн|erklär|explic|expliq|spieg)', word):
        return 'foreign_explain'
    if not roots and re.match(
            r'(рассказ|сказ|говор|спраш|отвеч|sprech|parl[aeio]|'
                r'raccont|habl|demand[aeio]|dis[aeio]|sag[et])', word):
        return 'foreign_speech'
    if word in {'dire', 'dit', 'dice', 'dijo', 'diz', 'nói'}:
        return 'foreign_speech'
