    return ''


def classify(word, previous, before_previous, text):
    group = family(word)
    if group == 'explain':
        if previous in SPEAKERS or before_previous in SPEAKERS:
            return 'speaker_explain'
        if previous in {'you', 'please'}:
            return 'request_explain'
        if word == 'explained':
            return 'past_explain'
        if word == 'explain' and text and text[0].isalpha():
            return 'unspaced_explain'
    if group == 'tell' and word == 'tell' and previous in {'', 'please'}:
        return 'request_tell'
    if group == 'say' and previous in SPEAKERS:
        return 'speaker_say'
    if word == 'understanding':
        return 'understanding'
    if word == 'learning':
        return 'learning'
    if word == 'think':
        return 'deliberate' if previous in {'to', 'me', 'must', 'should'} else 'think'
    if word in {'state', 'states', 'stated', 'stating'}:
        noun = (previous in {'united', 'the', 'a', 'of', 'in', 'this', 'these', 'many',
                            'several', 'two', 'new', 'final', 'starting', 'current'}
                or 'adjective' in wordnet.parts_of_speech(previous)
                or text.strip() in {'State', 'States'})
        if noun:
            return ('political_state' if text.strip() in {'State', 'States'}
                    else 'state_noun')
        if previous in SPEAKERS or previous in {'problem', 'question', 'theorem'}:
            return 'report_state'
        if word == 'states' or previous in {
                'to', 'and', 'or', 'please', 'can', 'shall', 'must'}:
            return 'state'
        return 'past' if word == 'stated' else 'state_noun'
    if word == 'said':
        return 'said'
    if word in {'asked', 'described', 'mentioned'}:
        return 'past'
    if word == 'says' or word == 'saying':
        return 'saying'
    if word == 'out' and previous in {'point', 'pointed', 'points', 'pointing'}:
        return 'point_out'
