def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '')
    _, tail, previous, before_previous, previous_group = carry
    text = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', text)
    word = match.group().lower() if match else ''
    # Han writing has no word-separating spaces: do not accumulate entire sentences.
    han = bool(regex.search(r'\p{Script=Han}', word))
    if word and not han and text[0].isalpha() and match.start() == 0:
        word = tail + word
    group = classify(word, previous, before_previous, text)

    if not group:
        if word == 'that' and previous_group in SPEECH | {
                'link_object', 'request_object'}:
            group = ('explain_that' if 'explain' in previous_group else
                     'speaker_that' if previous_group == 'speaker_say' else 'link_that')
        elif word == 'of' and previous_group == 'explanation':
            group = 'explanation_of'
        elif word == 'of' and previous_group in {'speech_noun', 'speak', 'mention'}:
            group = 'link_of'
        elif word == 'of' and previous_group in {
                'understanding', 'learning', 'understand'}:
            group = 'knowledge_of'
        elif word == 'of' and previous_group in {'state_noun', 'political_state'}:
            group = 'state_of'
        elif word == 'of' and previous == 'total':
            group = 'total_of'
        elif word == 'about':
            group = ('speech_about' if previous_group in
                     SPEECH | {'link_object', 'request_object'} else 'about')
        elif word == 'to' and previous_group in SPEECH | {
                'link_object', 'request_object'}:
            group = 'speech_to'
        elif word in OBJECTS and previous_group in SPEECH - {
                'said', 'say', 'saying', 'past'}:
            group = ('request_object' if previous_group == 'request_tell'
                     else 'link_object')
        elif word in {'the', 'a', 'this'} and previous_group in SPEECH | {'read'}:
            group = 'link_article'
    value = VALUES.get(group, 0.0)
