import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

FUNCTION_WORDS = frozenset("""
a an the this that these those its his her my your our their of in on at by to
for from and or but is are was were be been being as with into than then if
not no all some any each which who what when where how have has had do does did
can could would should will may might must it he she they we you i
""".split())
WORDS = re.compile(r"[A-Za-z]+")


@lru_cache(maxsize=50000)
def parts(word):
    word = word.lower()
    if word in FUNCTION_WORDS:
        return frozenset()
    return wordnet.parts_of_speech(word)


@lru_cache(maxsize=20000)
def head_classes(word):
    word = word.lower()
    return (wordnet.categories(word),
            wordnet.is_a(word, 'organization'),
            wordnet.is_a(word, 'building'),
            wordnet.is_a(word, 'award'))


def compound_value(text, token, matches):
    if not matches or matches[-1].end() != len(text):
        return 0.002
    word = matches[-1].group()
    if 'noun' not in parts(word):
        return 0.002

    # Count preceding content words, without crossing punctuation or a function
    # word. Capitals allow proper-name modifiers missing from the dictionary.
    modifiers = 0
    for j in range(len(matches) - 2, -1, -1):
        old = matches[j].group()
        gap = text[matches[j].end():matches[j + 1].start()]
        if old.lower() in FUNCTION_WORDS or not re.fullmatch(r'[ -]+', gap):
            break
        pos = parts(old)
        if not ('noun' in pos or 'adjective' in pos or old[0].isupper()):
            break
        modifiers += 1
        if modifiers == 8:
            break
    if modifiers == 0:
        return 0.002
    if modifiers == 1:
        return -0.003

    previous = matches[-2].group()
    categories, organization, building, award = head_classes(word)
    if not word[0].isupper():
        if zipf_frequency(previous.lower(), 'en') > 5:
            return 0.012
        if modifiers == 2:
            return 0.046
        return 0.25 if 'noun.group' in categories else 0.09

    if organization:
        if 'noun.location' in categories:
            return 0.13
        if len(token) <= 4:
            return 0.064
        if 'noun.person' in categories:
            return 0.37
        if 'noun.artifact' in categories:
            return 0.33 if modifiers == 2 else 0.85
        return 0.93
    if building:
        return 0.80
    if not previous[0].isupper():
        return 0.0
    if len(token) <= 3:
        return 0.025
    return 0.94 if award else 0.19


def decimal_value(before, token, integer):
    """A fitted, additive description of digits immediately following a dot."""
    number = int(integer)
    context = before[-80:].lower()
    value = -0.16
    value += 0.48 * (token == '0') + 0.045 * (token == '1')
    value += 0.38 * (number > 0) - 0.037 * min(number, 10)
    value += 0.016 * (len(integer) < 3)
    value += 0.25 * bool(re.search(r'\bversion\b', context))
    value += 0.10 * bool(re.search(r'licen[cs]e', context))
    value += 0.18 * bool(re.search(r'\bv\d+\.$', context))
    value += 0.23 * bool(re.search(r'\d+\.\d+\.$', context))
    value += 0.20 * bool(re.search(r'/|__|::|=', before[-40:]))
    return value


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        position, before = 0, ''
    else:
        _, position, before = carry
    token = prefix.token_strings[-1]
    text = (before + token)[-160:]
    state = (document, position + 1, text)
    matches = list(WORDS.finditer(text))

    if position == 0:
        word = matches[-1].group() if matches and matches[-1].end() == len(text) else ''
        space = bool(token[:1].isspace())
        if len(word) <= 2:
            return state, -0.054 if space else -0.24
        return state, -0.35 if space else -0.56
    if position == 1 and before == 'Title' and token == ':':
        return state, 4.29

    decimal = re.search(r'(\d+)\.$', before)
    if token.isascii() and token.isdigit() and decimal:
        return state, float(decimal_value(before, token, decimal.group(1)))
    return state, float(compound_value(text, token, matches))

