import re

READS = ()


def response(text, previous, word):
    s = text.lstrip()
    if not s:
        return 0.0
    low, p = s.lower(), previous.lower()
    spaced, capital = s != text, s[0].isupper()
    split_w = (not spaced and p.endswith('w')
               and not (capital and previous.islower()))
    stem = 'w' + low if split_w else low

    if re.fullmatch(r'awards?', low):
        if low.endswith('s'):
            return 3.5 if capital else 2.8
        if not spaced:
            return 2.8 if capital else 6.0
        return 4.3 if capital else 4.0
    if low == 'awarded':
        return 2.4
    if stem.startswith('washington'):
        return -0.7
    if re.fullmatch(r'wash(?:ed|ing|ers?)?', stem):
        return -7.8 if split_w else (-6.4 if low == 'wash' else -5.0)
    if re.fullmatch(r'ward(?:en)?s?', stem):
        if split_w:
            return 13.0 if previous.endswith('W') and low != 'arden' else 8.0
        if spaced:
            return 7.5 if capital else 6.5
        if not word:
            return 8.0
        return 2.0 if p in ('re', 'to', 'back', 'for') else 4.0
    if re.fullmatch(r'(in|out|up|down|on)wards?', low):
        value = {'inward': 3.3, 'outward': 3.0, 'upward': 2.4,
                 'downward': 1.6, 'onward': 0.7}[low.rstrip('s')]
        return value * (0.75 if low.endswith('s') else 1.0)
    if re.fullmatch(r'wast(?:e|ed|ing)?', low):
        return -0.9
    if low in ('war', 'wars'):
        return 1.9 if capital else (0.7 if spaced else 2.8)

    if split_w:
        if re.fullmatch(r'ad(?:e[ds]?|ing|ers?)', low):
            return 5.5
        if re.fullmatch(r'as(?:s(?:er|ert)?|m)|ann(?:a|er)?', low):
            return -4.3
        if re.fullmatch(r'är|äng', low):
            return 7.0
        if re.fullmatch(r'ä|äh|änd', low):
            return 2.5
        if re.fullmatch(r'ds?|ird|arg|art', low):
            return 4.5
    if not spaced:
        w = word.lower()
        if re.search(r'wä$', w) and low.startswith(('r', 'ld')):
            return 6.0
        if re.search(r'wär$', w) and low.startswith(('t', 'd')):
            return 6.0
        if w.endswith('ward') and low.startswith(('en', 'ed', 'ian')):
            return 1.7 if low.startswith('ian') else 4.0
        if w.endswith('wash') and low.startswith(('es', 'er', 'ing', 'ed')):
            return -4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, previous, word = ((doc, '', '') if carry is None or carry[0] != doc
                         else carry)
    text = prefix.token_strings[-1]
    value = response(text, previous, word)
    word = re.search(r'[^\W\d_]*\Z', (word + text)[-36:]).group()
    return (doc, text, word), float(value)

"""Approximate an Indonesian-context contrast between grammatical prefixes
and other unfinished word pieces.

Recent words supply decaying language evidence. Indonesian corpus frequencies
estimate whether the spelling seen so far is a complete word or just a prefix.
`di`, `ke`, and pieces of passive di- get positive responses. Other incomplete
pieces get small negative responses, adjusted for syllable shape and productive
prefixes. This is a coarse approximation, not a token-by-token dictionary.
Repeated middle dots have a separate small positive response.
"""
import re
from collections import defaultdict
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
PRONOUNS = set('saya kita anda mereka kami kamu dia beliau aku'.split())
PREFIXES = set('me men mem meng meny pe pen pem peng peny ber per ter se'.split())
ENGLISH_FUNCTION_WORDS = set(
    'the of and to a is in that for it as be with was on are this have has '
    'not from which'.split()
)

# How frequent are Indonesian words beginning with each spelling?
PREFIX_MASS = defaultdict(float)
for word in top_n_list('id', 30000):
    if word.isascii() and word.isalpha():
        frequency = 10 ** zipf_frequency(word, 'id')
        for length in range(1, len(word) + 1):
            PREFIX_MASS[word[:length]] += frequency


@lru_cache(maxsize=100000)
def language_evidence(word):
    lower = word.lower()
    if lower in ENGLISH_FUNCTION_WORDS:
        return -0.7
    if len(lower) < 3:
        return 0.0
    indonesian = zipf_frequency(lower, 'id')
    if indonesian < 4.5:
        return 0.0
    competing = max(zipf_frequency(lower, language) for language in
                    ('en', 'it', 'es', 'fr', 'de', 'pt', 'tr', 'cs'))
    difference = indonesian - competing
    evidence = max(0.0, min(1.0, indonesian - 4.5)
                   * min(1.5, difference - 1.0))
    # An ambiguous capitalized word may just be a name.
    if word[0].isupper() and difference < 2.5:
        evidence *= 0.4
    return evidence


@lru_cache(maxsize=100000)
def completeness(word):
    word = word.lower()
    frequency = zipf_frequency(word, 'id')
    mass = PREFIX_MASS.get(word, 0.0)
    if not mass:
        return float(frequency >= 5.0)
    return min(1.0, 10 ** frequency / mass)


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    if carry is None or carry[0] != document:
        pending, score = '', 0.0
    else:
        _, pending, score = carry
    before = pending
    token = prefix.token_strings[-1]
    signal = 0.0
    for part in re.findall(r'[A-Za-z]+|[^A-Za-z]+', token):
        if part.isascii() and part.isalpha():
            pending = (pending + part)[-64:]
        elif pending:
            signal += language_evidence(pending)
            pending = ''
    score = max(0.0, 0.94 * score + signal)
    if '<|endoftext|>' in token:
        pending, score = '', 0.0
    evidence = score + 0.5 * max(0.0, language_evidence(pending))
    grammatical_gate = min(1.0, max(0.0, evidence - 0.5))
    fragment_gate = min(1.0, max(0.0, evidence - 1.5))
    carry = (document, pending, score)

    stripped = token.strip().lower()
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        return carry, 0.49
    match = re.search(r'[A-Za-z]+$', token)
    if match is None:
        return carry, 0.0
    piece = match.group().lower()
    starts_word = match.start() > 0 or not before
    missing = 1.0 - completeness(pending)

    background = 0.0
    if starts_word:
        if piece == 'di':
            return carry, -0.30 + 7.71 * grammatical_gate
        if piece == 'ke':
            return carry, -0.15 + 4.20 * grammatical_gate
        if piece == 'd':
            return carry, -0.07 + 2.07 * grammatical_gate
        if len(piece) == 3 and piece.startswith('di'):
            background = -0.12
        if len(piece) > 2 and piece.startswith('di') and missing > 0.5:
            return carry, background + 3.38 * missing * grammatical_gate
    elif before.lower() == 'd' and piece.startswith('i'):
        return carry, 0.96 * grammatical_gate

    vowels = sum(letter in 'aeiou' for letter in piece)
    response = (-1.48 if starts_word else -0.91) * missing
    if starts_word and len(piece) >= 3 and vowels == 1:
        if piece[-1] not in 'aeiou':
            response -= 0.72 * missing
    if vowels >= 2:
        response += 0.65 * missing
    if match.group()[0].isupper():
        response += 0.76 * missing
    if starts_word:
        if piece in PREFIXES:
            response += 0.53 * missing
        if piece.startswith(('ber', 'ter', 'per', 'ke')):
            response += 1.56 * missing
        if piece in PRONOUNS:
            response += 0.98
    return carry, float(background + fragment_gate * response)

