        value = 2.3                 # Python function declaration
    elif initial and t == 'class':
        value = 0.97                # Class declaration
    elif initial and t == 'package':
        value = 0.57                # Package declaration
    elif len(t) >= 2 and set(t) == {'·'}:
        value = -0.5                # Repeated middle-dot separator
    elif word.startswith('данн'):
        value = -2.5 if 'данн' in t else -3.5
    elif (s[:1].isspace() and t == 'дан') or s.strip() == 'Дан':
        value = -1.2
    elif vi and t.startswith('d'):
        if t == 'd':
            value = -5.5
        elif ud.normalize('NFD', t).startswith('di'):
            value = -4.5
        else:
            value = -1.6
    elif vi and continues and old_word.startswith('d'):
        value = -3.6
    elif vi and old_word == 'dữ' and t.startswith('liệu'):
        value = -1.8                # Vietnamese 'data' phrase
    elif central and t == 'd':
        value = -0.6
    elif previous.strip().lower() == 'd' and continues and (
        any(ud.combining(c) for c in ud.normalize('NFD', t))
        or any(c in t for c in 'øæ') or central
