import re

READS = ()
FINANCIAL = {
    'bank', 'savings', 'checking', 'capital', 'equity', 'funding', 'joint', 'deposit'
}


def response(token, previous, tail):
    word = token.strip(' ._/\t\r\n')
    low = word.lower()
    prev = previous.strip().lower()
    text = tail.decode('utf-8', errors='ignore')
    # Whole lexical items; spacing and case distinguish prose from identifiers.
    if low in ('account', 'accounts'):
        if word.isupper():
            return -5.5 if token.startswith(' ') else -2.5
        if word == 'account':
            if prev in ('into', 'to'):
                return -0.2 if prev == 'into' else -0.8
            if prev in ('not', 'cannot', 'can', 'could', 'may', 'would', 'will'):
                return -0.15
        if prev in FINANCIAL:
            return -5.3
        if token.startswith(' '):
            if low == 'accounts':
                return -2.5
            return -3.2 if word[:1].isupper() else -2.9
        return -2.1 if word[:1].isupper() else -1.4
    if low in ('customer', 'customers'):
        return -2.5 if token.startswith(' ') else -1.7
    if low in ('client', 'clients'):
        return -0.25 if low == 'client' else -0.55
    if low in ('contract', 'contracts', 'contractor', 'contractors'):
        return -0.3 if low in ('contract', 'contractor') else -0.85
    # Chinese account/customer/household terms and their shared written root.
    if word in ('户', '戶'):
        return -8.0 if word == '户' else -9.0
    if word == '戸' or (token.endswith('\ufffd') and text.endswith('戸')
                        and 0x80 <= tail[-1] <= 0xBF):
