    if low in ('账户', '帐户', '賬戶', '帳戶', '开户', '開戶'):
        return -5.2
    if low in ('客户', '客戶'):
        return -2.9
    if low in ('用户', '用戶'):
        return -2.1
    if low.endswith(('户', '戶')):
        return -3.0
    if word == '客' and previous.endswith(('顾', '顧')):
        return -4.5
    # Romance and Germanic spellings of account / customer.
    if low in ('cuenta', 'cuentas', 'conta', 'conto', 'conti'):
        return -3.6
    if low in ('compte', 'comptes', 'compt'):
        return -2.6
    if low in ('cont', 'cuent') and token.startswith(' '):
        return -0.6 if low == 'cont' else -1.8
    if low in ('kont', 'konto', 'konten', 'kunde', 'kunden'):
        return -2.4
    if low in ('счет', 'счёт', 'клиент', 'клиенты', 'cliente', 'clientes'):
        return -1.2
    # A continuation must touch the previous token, without intervening space.
    if token != word:
        return 1.2 if token == '··' else 0.0
