        return -9.0
    if low in ('uent', 'uenta') and previous.lower().endswith('c'):
        return -5.3
    if low in ('te', 'tes') and joined.endswith(('comte', 'comtes')):
        return -4.0
    if low in ('a', 'as', 'o', 'i', 'es'):
        if re.search(r'(cuent|cont|compt|kont)' + low + r'$', joined):
            return -6.0 if low == 'as' else (-3.7 if low == 'i' else -5.5)
    if low in ('un', 'una', 'unas', 'und', 'unde', 'unden', 'ont', 'онт'):
        if previous.lower().endswith(('c', 'k', 'к')):
            if low.startswith('un') and previous.lower().endswith('c'):
                return -1.2
            return -2.5 if low in ('un', 'una', 'unas') else -3.5
    if word == 'COUNT' and previous.endswith('K'):
        return -5.9
    if low == 'count' and previous.lower().endswith(('vis', 'ac', 'dis')):
        return -5.5
    if low in ('er', 'ers', 'ustomer', 'ustomers'):
        if re.search(r'customers?$', joined):
            return -5.0 if len(low) == 2 else (-4.0 if len(low) == 3 else -2.5)
