        if low == 'cont' and joined.endswith('accont'):
            return -4.8
        return -0.6 if low == 'cont' else -1.8
    if low == 'pt' and previous.lower().endswith('com'):
        return -5.5
    if word == 'ун' and previous.endswith('ка'):
        return -2.3
    if word == 'ウン' and previous.endswith('カ'):
        return -1.3
    if word in ('ウ', 'ント') and joined.endswith(('カウ', 'ウント')):
        return -6.0
    if token == '··':
        return 1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', b'') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    tail = (tail + prefix.token_bytes[-1])[-96:]
    value = response(token, previous, tail)
    return (doc, token, tail), value

"""A local approximation to the component's escaped-text responses.

A token after a backslash gets a response based on familiar syntax: opening
braces/brackets, dollar signs, quotes, stars, and short LaTeX command pieces.
Repeated backslashes weaken braces and neutralize the dollar response.
A bracket escape inside one token gets a smaller response. Ordinary interior
text defaults to zero. Separate rules approximate negative document-start
responses and runs of middle-dot leaders. Constants are coarse training means;
this does not explain every lexical or non-Latin response of the component.
"""

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if len(s) >= 2 and not s.strip("·"):
        return None, -2.36

    first = (prefix.position == 0
             or prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        if s == "<|endoftext|>":
            value = -3.6
        elif s.isascii() and s and s[0].isalpha():
            value = -0.68 if s[0].isupper() else -0.47
        else:
            value = -0.25
        return None, value

    previous = prefix.token_strings[-2]
    if not previous.endswith("\\"):
        return None, 0.5 if s == "\\[" else 0.0

    depth = len(previous) - len(previous.rstrip("\\"))
    if s.startswith("$$"):
        value = 0.7 if depth == 1 else 0.0
    elif s.startswith("$") and depth > 1:
        value = 0.0
    elif s.startswith("$"):
        value = -2.9 if len(s) > 1 and s[1] in "({" else -1.65
    elif s.startswith(('"/', '",')):
        value = -1.1
    elif s.startswith('"'):
        value = -0.3
    elif s.startswith("{"):
        value = (5.3 if s.startswith("{\\") else 4.2) / 2 ** (depth - 1)
    elif s == "lbrace":
        value = 4.0
    elif s.startswith("[") and not any(c.isspace() for c in s):
        value = 0.4 if previous.endswith("\\\\") else (
            0.6 if '"' in previous else 1.5)
    elif s and not s.strip("\\"):
        value = 4.1 if previous.rstrip("\\").endswith(" ") else (
            0.7 if depth > 1 else 0.0)
    elif s.startswith('\\"'):
        value = 1.1
    elif s.startswith("*") or s in {"%", "!", "!\\", "|\\"}:
        value = 1.0
    elif s == "&":
        value = 0.3 if previous.endswith("\\\\") else 3.3
    elif s == "ne":
        value = 1.8
    elif s == "’":
        value = 1.7
    elif s.isascii() and s.isalpha() and s[0].isupper():
        value = 0.4
    elif s in {"i", "j"}:  # LaTeX dotless-letter commands
        value = 1.2
    elif s in {"to", "tan"}:
        value = 0.5
    else:
        value = 0.0
    return None, value

"""Approximate an arrow-family spelling detector with local text rules.

Arrow/narrow/marrow, split r+row, and warrior/roar forms give negative
pulses. Case and token boundaries change their strength. LaTeX directional
arrow commands are exempt. A few Chinese arrow, sword, bravery and
narrowness characters give negative pulses too: this is not a general
semantic weapons classifier.

Plain row, split r+av/aw, and two partial UTF-8 Han prefixes are positive.
Amplitudes are rounded training estimates. Unmatched tokens predict zero;
the short text tail resets at each document boundary.
"""
import re

READS = ()

def predict(piece, before, raw=b'', tail=b''):
    # Split second byte: U+7D40–7D7F or U+7DC0–7DFF (silk radical).
    if tail.endswith(b'\xe7') and raw in (b'\xb5', b'\xb7'):
        return 5.7
    s = piece.strip()
    low = s.lower()
    attached = bool(piece and not piece[0].isspace()
                    and before and before[-1].isalpha())
    prev = before.lower()
    caps = bool(s and s[0].isupper())
    if 'arrow' in low:
        command = low.lstrip('\\')
        directions = r'(?:left|right|up|down|leftright|updown)'
        if re.fullmatch(r'(?:long)?' + directions + r'arrows?', command):
            return -0.0
        if low.startswith('narrow'):
            if caps:
                return -6.6
            return -4.5 if low == 'narrowly' else -2.7
        if low == 'marrow':
            return -2.5
        if (re.search(r'\\[a-z]*$', prev)
                or re.search(r'\{\s*(left|right)$', prev)):
            return -0.0
        if attached and prev.endswith('py'):
            return -11.7
        if not attached and re.search(r'\b(left|right|up|down)$', prev):
            return -3.7
        return -7.7 if caps else -7.0
    if low in ('row', 'rows', 'rowing'):
        if attached and prev.endswith('r'):
            if prev.endswith('ar'):
                return -8.9
            if prev.endswith('fur'):
                return -8.4
            if prev.endswith('ur'):
                return -5.4
            return -3.8
        return 0.3
    if low in ('rior', 'riors') and attached and prev.endswith('war'):
        return -9.1
    if low in ('warrior', 'warriors'):
        if caps:
            return -3.7
        return -3.8 if low == 'warrior' else -2.3
    if low == 'aring' and attached and prev.endswith('ro'):
        return -5.3
    if low in ('roaring', 'soaring'):
        return -3.1 if low == 'roaring' else -1.6
    if attached and prev.endswith('r'):
        if low.startswith('av'):
            if prev.endswith('rr'):
                return 5.5
            if len(prev) > 1 and prev[-2] in 'aeiou':
                return 1.5
            return 0.1
        if low.startswith('aw'):
            if len(prev) > 1 and prev[-2] in 'aeiou':
                return 3.3
            return 0.2
    # Chinese: arrow, sword, bravery, heroism, fierceness, narrowness.
    if s == '箭':
        return -8.6
    if s in ('剑', '劍'):
        return -4.2
    if s == '勇':
        return -3.8
    if s in ('侠', '俠'):
        return -3.5
    if s == '猛':
        return -1.5
    if s in ('窄', '狭', '狹'):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    piece = prefix.token_bytes[-1]
    value = predict(piece.decode('utf-8', 'replace'),
                    tail.decode('utf-8', 'ignore'), piece, tail)
    return (doc, (tail + piece)[-96:]), value

