              'media', 'mnt', 'opt', 'proc', 'root', 'run', 'sbin',
              'srv', 'sys', 'tmp', 'usr', 'var', 'workspace'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    fresh = len(prefix.token_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2])
    prev = '' if fresh else prefix.token_strings[-2]
