            else:
                value = 1.45 if n <= 8 else 1.2
        elif fresh:
            value = 0.72
        elif prev.endswith(('\n', '\\n')):
            value = 0.05
    elif s == '\t' and white:
        value = 1.4 if ' ' in prev else 0.8
    elif s == '\xa0' and white:
        value = (1.7 if len(prev) % 4 == 3 else
                     0.7 if len(prev) == 2 else
                     0.2 if len(prev) == 1 else -0.15)
    elif s.startswith('\t') and s[1:] and set(s[1:]) == {' '}:
        value = -0.20 if len(s) <= 4 else -0.06
    elif s in ('    ', '        ') and prev.endswith(' \n'):
        value = 0.45

    mark = s.strip(' ')
    if mark in ('//', '#'):
        if white:
            value = 1.15 if mark == '//' else 1.05
            if prev == ' ':
                value = 0.9 if mark == '//' else 0.35
            elif s == '//':
                value = 1.0
        elif prev.endswith(('\\n', '\\t')):
            value = 1.4
        elif prev.endswith('\n'):
            value = 0.6 if s.startswith(' ') else 0.9
            if mark == '#' and prev == '\n\n':
                value = 0.5
        elif prev.endswith('`'):
            value = 1.35
        else:
            value = 0.25 if mark == '//' else 0.0
    elif mark == '--':
        value = 0.85 if white or prev.endswith('\n') else (
            0.32 if s.startswith(' ') else 0.1)
    elif mark == '/*':
        value = 0.6 if white else 0.25
    elif mark in ('*', '*\n') and s.startswith(' '):
        value = 0.22 if white or prev.endswith('\n') else -0.03
    elif mark in ('///', '///\n'):
        value = 0.23
    elif s == '``' and white:
        value = 0.75

    # Standard filesystem segments, rather than arbitrary filenames.
    if s in UNIX_ROOTS and prev.endswith('/'):
        value = 1.75 if s in {'usr', 'opt', 'workspace', 'home'} else 1.0
    elif s == '/workspace':
        value = 0.60
    elif s == '/local' and prev == 'usr':
        value = 1.4
    elif s in {'Users', 'Applications', 'Volumes', 'Library', 'System'}:
        if prev.endswith('/'):
            value = 2.2
        elif prev.endswith('\\'):
            value = 1.6
    elif s in (' /', ' "/', " '/", ' `/', ' ~/', '/.'):
        value = 0.55 if s != ' /' else 0.25
        if s == ' /' and prev in ('cd', ' cd', ':', ' >'):
            value = 0.77
