          and 'A' <= prev.strip() <= 'Z'):
        value = 2.1

    # Special responses to document-opening formatting.
    if fresh and s == 'Title':
        value = -2.12
    elif not fresh and carry == 'title' and s == ':':
        value = 7.48
    elif fresh and s == '//\n':
        value = 6.45
    elif s == '\r' and (fresh or carry == 'carriage'):
        value = 4.15
    elif s == '··' and (fresh or prev == '··'):
        value = 1.35

    state = 'title' if fresh and s == 'Title' else (
        'carriage' if s == '\r' and (fresh or carry == 'carriage') else None)
    return state, value

"""Approximate the dominant early-Arabic-yeh response.

Arabic ي and Persian ی usually give positive responses, especially early
in a stem and at the beginning of a continuation token. Later suffixes
respond less. Some response persists for one token, particularly on shadda.
Common Arabic article prefixes are excluded when counting stem letters.
Middle-dot-only tokens have a separate negative response. Most other text
is zero.
These spelling rules do not capture every rare activation.
"""
import unicodedata as ud

READS = ()
YEH = 'يی'
# Rows: letters before yeh in the stem, capped at four.
# Columns: token ends here; next letter alef; ta marbuta; other letter.
RESPONSE = (
    (1.47, .58, .00, .84),
    (1.66, .75, .78, 3.85),
    (.96, .17, .80, 2.64),
    (.24, .14, .27, 1.04),
    (.00, .01, .10, 1.16),
)
ECHO = (.22, 1.03, 1.04, .46, .41)


def arabic_letter(c):
    return c.isalpha() and 'ARABIC' in ud.name(c, '')


def stem(word):
    if word.startswith(('وال', 'فال', 'بال', 'كال')):
        return word[3:]
    return word[2:] if word.startswith('ال') else word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    word = tail
    for i, c in enumerate(token):
        if arabic_letter(c):
            word += c
            if c in YEH:
                position = min(4, len(stem(word)) - 1)
                following = ''
                for ch in token[i + 1:]:
                    if arabic_letter(ch):
                        following += ch
                    elif ud.category(ch)[0] != 'M':
                        break
                kind = (0 if not following else 1 if following[0] == 'ا'
                        else 2 if following[0] == 'ة' else 3)
                value += RESPONSE[position][kind]
                if kind == 3:
                    if i > 0 and arabic_letter(token[i - 1]):
                        value -= 1.28
                    if len(following) >= 2:
                        value -= .23
                if kind == 0 and i == 0:
                    value += .28
        elif ud.category(c)[0] != 'M':
            word = ''

    if any(c in previous for c in YEH):
        if token and arabic_letter(token[0]):
            positions = [i for i, c in enumerate(stem(tail)) if c in YEH]
            if positions:
                value += ECHO[min(4, positions[-1])]
        if token.startswith('ّ'):
            value += 2.16
    if any(arabic_letter(c) for c in token):
        value -= .035
    if token.startswith('ّ'):
        value += .054
    if token and set(token) == {'·'}:
        value -= .80
    return (doc, word[-40:], token), float(value)

"""Recognize indented control-flow headers and prose navigation references.

Loop and exception keywords are strongest after indentation (also when code is
escaped inside a string).  Ordinary prose uses of these words stay near zero.
Conversely, 'for' and 'to' introducing a clicked destination or a 'see ...'
reference receive a negative value. Other tokens are left at zero. The short
text buffer resets at each document; strengths approximate training observations.
"""
import re

READS = ()
# Space-indented, tab-indented, and unindented line-start strengths.
CONTROL = {
    'for': (6.6, 7.2, 3.2),
    'while': (8.5, 9.8, 6.8),
    'try': (8.7, 8.0, 6.2),
    'do': (5.4, 4.5, 1.7),
    'foreach': (4.6, 4.6, 2.3),
    'switch': (1.3, 2.5, 0.7),
    'defer': (2.8, 2.5, 1.0),
}
REFERENCE = re.compile(
    r'\b(see|click|press|check|visit|refer|scroll|tap|enter)\b', re.I)
LOCATORS = {'here', 'below', 'above'}
OBJECTS = {'page', 'button', 'link', 'icon', 'license', 'section'}
REFERENCE_NOUNS = re.compile(
    r'\b(text|manual|documentation|chapter|section|figure|table|license|'
    r'example|details|page|references|tests|notes)\b', re.I)
CODE = re.compile(r'[={}\[\];]|\b(def|func|var|int|return|print|echo)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, prev = '', ''
    else:
        _, tail, prev = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    value = 0.0
    if word.lower() in CONTROL:
        space, tab, line = CONTROL[word.lower()]
        horizontal = bool(prev) and not prev.strip(' \t\u00a0')
        if s.startswith('\t'):
            value = tab + (0.8 if horizontal else 0.0)
        elif tail.endswith('\\t'):
            value = tab - 1.0
        elif horizontal:
            if len(prev) > 1:
                value = space
                if '\t' in prev:
                    value *= 0.8
                if word == 'for':
                    value -= min(2.0, max(0, len(prev) - 7) * 0.12)
            else:
                empty_line = not tail.split('\n')[-1].strip()
                value = space if empty_line else space * 0.45
        elif tail.endswith(('\n', '\r', '\\n')):
            value = line if CODE.search(tail) else line * 0.18
            if word == 'try' and tail.endswith('\\n') and prev == 'n':
                value = 1.5
        elif prev.rstrip().endswith((';', '{', '}')):
            value = line * 0.65
        elif not s.startswith(' ') and prev.endswith(('`', '"', "'", '.')):
