        matches = list(REFERENCE.finditer(tail))
        if matches:
            match = matches[-1]
            action = match.group().lower()
            distance = len(tail) - match.end()
            locator = prev.strip().lower() in LOCATORS
            object_ = prev.strip().lower() in OBJECTS
            if word == 'for':
                if action == 'see' and distance < 100:
                    phrase = tail[match.end():]
                    reference = REFERENCE_NOUNS.search(phrase)
                    citation = any(c in phrase for c in
                                   ('[', '`', 'http', '.org', '.com'))
                    ended = re.search(r'[.!?]\s+[A-Z]|\)[,.]|\n\s*\n', phrase)
                    perception = phrase.lstrip().lower().startswith(
                        ('that ', 'what ', 'when ', 'against '))
                    if ended or perception:
                        pass
                    elif locator:
                        value -= 12.0 if prev.strip().lower() == 'below' else 10.0
                    elif reference or citation:
                        value -= 5.8
                    elif distance < 25:
                        value -= 2.2
                elif action == 'click' and distance < 30 and locator:
                    value -= 8.8
                elif action in ('check', 'visit', 'refer') and distance < 30:
                    value -= 4.5 if locator else 2.0
            elif (action in ('click', 'press', 'enter', 'scroll', 'tap')
                  and distance < 25):
