"""Layer 1, MLP down-projection, component 5871: an "explanation / meaning link" feature.

Plain-language summary of what it responds to:
  * "for" right after a noun of explanation or reason ("the reason for", "the evidence
    for", "the basis for", "the word for", "the term for"): strongest, about 2 to 3.
  * "for" after other nouns that name a meaning or specification ("the formula for",
    "the code for", "the model for"): moderate, about 0.7.
  * "behind" and "why" after "reason" ("the reason behind", "the reason why").
  * verbs of representing and explaining: "represents", "represent", "explains",
    "describes", "illustrates" (weaker for other verbs of showing).
  * "to"/"with" after relation verbs ("corresponds to", "associated with").
  * the colon after a "Title" label, and "be" in "to be".
  * a mild negative on the first token of each document.
Everything else is close to zero. Values are rough calibrated least-squares weights.
"""
READS = ()

STRONG_NOUNS = {
    "reason", "reasons", "cause", "causes", "explanation", "explanations", "evidence",
    "basis", "word", "words", "term", "terms", "name", "names", "factor", "factors",
}
MEANING_NOUNS = STRONG_NOUNS | {
    "formula", "formulas", "equation", "equations", "code", "model", "models", "account",
    "accounts", "expression", "mechanism", "source", "syntax", "recipe", "function", "role",
    "statement", "probability", "estimate", "framework", "foundation", "reference", "format",
    "responsible", "meaning", "definition", "symbol", "abbreviation", "acronym", "label",
    "notation", "representation", "answer", "solution", "proof", "justification",
    "synonym", "predictor", "predictors",
}
RELATION_VERBS = {
    "correspond", "corresponds", "corresponding", "contribute", "contributes",
    "contributing", "associated", "consistent", "related", "linked", "rise", "responsible",
}


def weight(cur, prev):
    """Activation (roughly) for the current word, given the word before it."""
    if cur == "for":
        if prev in STRONG_NOUNS:
            return 2.0
        return 0.7 if prev in MEANING_NOUNS else 0.1
    if cur == "behind":
        return 2.5 if prev in ("reason", "reasons") else 0.4
    if cur == "why":
        return 1.2 if prev in ("reason", "reasons") else 0.4
    if cur.startswith("represent"):
        return 0.6
    if cur.startswith("explain"):
        return 0.35
    if cur.startswith(("describ", "illustrat", "demonstrat")):
        return 0.2
    if cur in ("to", "with") and prev in RELATION_VERBS:
        return 0.3
    if cur == "be" and prev == "to":
        return 0.17
    if cur == "of" and prev in MEANING_NOUNS:
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip().lower()
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.2  # first token of a document
    prev = toks[-2].strip().lower()
    if cur == ":" and prev == "title":
        return None, 0.5
    return None, weight(cur, prev)

