def activation(token, before, position):
    word = token.strip()
    low = word.lower()
    tail = before.rstrip()
    match = re.search(r'([A-Za-z]+)$', tail)
    previous = match.group(1).lower() if match else ''

    if word == ':' and before == 'Title':
        return 3.871
    if position == 0 and token == '//\n':
        return -3.192
    if len(word) > 1 and set(word) == {'·'}:
        return 0.978
    if low == 'permalink':
        return -1.85
    if word == 'udos' and tail.endswith('K'):
        return -0.59  # Completion of the forum's "Kudos" label.
    if word == 'V' and re.search(r'Q\d{1,2}\s*$', tail):
        return -0.88  # Verbal score following a GMAT quantitative score.
    if low == 'mark' and previous == 'question':
        return 2.318

    if low == 'pass':
        if word == 'PASS':
            if tail.endswith('---'):
                return 0.90
            return -0.41 if tail.endswith(('✓', '✔', '✅')) else 0.0
        if previous in {'test', 'tests'}:
            return -1.60
        return -0.45 if previous == 'to' else 0.0
    if low == 'passed' and previous in {'test', 'tests', 'suites'}:
        return -0.68

    if low in {'exam', 'exams'}:
        if previous in {'practice', 'final', 'chapter'}:
            return -0.36
        if previous in {'certification', 'licensing'}:
            return -2.02
        return -1.71 if word[0].isupper() else -0.80
    if low in {'certification', 'certifications', 'certified'}:
        return 0.20 if previous == 'labor' else -0.64
    if low in {'question', 'questions'} and previous == 'test':
        return -1.69
    if low in {'material', 'materials'} and previous in {
        'study', 'reference', 'reading', 'preparation', 'course', 'training'
    }:
        return -1.55
    if low == 'preparation' and previous == 'exam':
        return -1.94
    if low in {'test', 'tests'} and previous == 'practice':
        return -0.75
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = activation(token, before, position)
    return (document, (before + token)[-180:], position + 1), value

