ENDINGS = {
    'り': 1.4, 'み': 1.4, 'き': 1.0, 'い': 0.56,
    'し': 0.24, 'び': 0.3, 'じ': 0.4, 'ち': 0.4,
    'る': 0.5, 'れ': 0.5, 'れて': 0.5, 'いて': 0.4,
    'って': 0.27, 'わ': 0.6, 'わり': 1.7, 'なり': 1.6,
    'ね': 1.6, 'ぬ': 1.5, 'っ': 0.9,
    'て': 0.2, 'め': 0.2, 'めて': 0.2, 'んで': 0.25,
    'た': 0.25, 'ら': 0.3, 'せ': 0.3, 'え': 0.15,
    'べ': 0.25, 'ば': 0.2, 'った': 0.1, 'れた': 0.4,
