import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# These are vowel-led grammatical endings, not individual word identities.
S_ENDINGS = {
    'e': -2.1, 'es': -1.33, 'ed': -1.54, 'en': -.76,
    'er': -.29, 'ers': -.66, 'ing': -2.13, 'ies': -.75,
}
SS_ENDINGS = {
    'e': -.18, 'es': -.86, 'ed': -.48, 'en': -.19,
    'er': -.06, 'ers': -.39, 'ing': -.49,
}


def ending(text):
    s = text.lower()
    for tail in ('ss', 'zz', 'ch', 'sh'):
        if s.endswith(tail):
            return tail
