    elif before in ('ss', 'zz'):
        value += SS_ENDINGS.get(s, 0.0)
    elif before in ('x', 'ch', 'sh', 'f') and s in ('e', 'es', 'ed', 'ing'):
        value -= .33

    if s.isascii() and s.isalpha() and len(s) <= 6:
        if 'se' in s:
