        if before and re.fullmatch(r'[a-z]{0,2}si[a-z]{0,2}', s):
            value -= .05
            if re.fullmatch(r'[aeiou]+si[a-z]{0,2}|sings?', s):
                value -= .14
        if before and re.fullmatch(r'[aeiou]*z[eiaou][a-z]{0,2}', s):
            value -= .08

    if token[:1].isspace():
        word = s.strip()
        if word.isascii() and word.isalpha():
            frequency = zipf_frequency(word, 'en')
            rarity = max(0, 5.5 - frequency) if frequency >= 3.2 else 0
            rarity = min(2, rarity) if len(word) >= 4 else 0
            if re.fullmatch(r'[a-z]{0,6}se(?:s|d)?', word):
                value -= .12 * rarity * (len(word) <= 5)
                if re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]*[aeiou]+[lnr]?se(?:s|d)?', word):
                    value -= .07 * rarity
            if re.fullmatch(r'[a-z]{0,5}sing', word):
                value -= .07 * rarity
