        word = old_word + word
    word = word[-40:]

    # These are spelling-sensitive completions, not all uses of the word.
    piece = text.lower()
    if piece == 'ishops' and word.endswith('archbishops'):
        value = 1.08
    elif piece in ('brief', 'rief') and word.endswith('debrief'):
        value = 0.62 if piece == 'brief' else 0.40
    elif piece == 'arrass' and word.endswith('débarrass'):
        value = 0.48
    elif piece == 'versed' and word == 'reversed':
        previous = prefix.token_strings[-2] if prefix.position else ''
        before = ''
        if prefix.position > 1 and prefix.document_ids[-3] == document:
            before = prefix.token_strings[-3].strip()
        is_list_call = previous.endswith('(re') and before == 'list'
        value = 0.88 if is_list_call else 0.26
    elif old_word.endswith('debrief') and piece in ('ing', 'ed'):
        previous = prefix.token_strings[-2].lower()
        value = -0.26 if piece == 'ing' and previous == 'rief' else -0.18
    elif old_word.endswith('débarrass') and piece == 'er':
        value = -0.24
    elif initial:
        value = first_token(text)
    else:
        part = text.strip()
        if not text[:1].isspace():
            value = -0.024 if part.islower() and part.endswith('ed') else 0.0
            if part.islower() and not part.endswith('ed'):
                value = -0.0055
        elif sum(ch.isalpha() for ch in text) > 8:
            value = -0.014 if part.endswith('ed') else -0.0036
        else:
            value = 0.0007
    return (document, word), value

programs.haiku:
"""Layer-1 MLP down-projection component 5877.

What it does, in plain terms
  Almost always near zero: on ordinary tokens its activation is a diffuse, token-specific
  wobble of about 0.04 in size, with no concept behind it that I could find (no simple
  word class, script, or position explains it).

  Two things stand out and are what this program predicts:
  1. The first token of a document segment. A packed row starts a segment, and so does
     the token right after <|endoftext|>. That token has no earlier context, so its
     activation depends on what the token is: digits, all-caps words and single letters
     give about +0.3 to +0.4; line breaks +0.25; punctuation and space-led words about
     +0.1; unspaced ordinary words about 0; CJK characters slightly negative.
  2. The horizontal line extension character "⎯", as in ascii-art rules, drives the
     component strongly negative (about -1.75).

  Every other position is predicted as 0.
"""

READS = ()

BAR = "⎯"


def _is_cjk(s):
    return any(
        "一" <= c <= "鿿" or "぀" <= c <= "ヿ" or "가" <= c <= "힯"
        for c in s
    )


def _segment_start_value(s):
    core = s.strip()
    if _is_cjk(s):
        return -0.05
    if core.isdigit() or (core.isalpha() and core.isupper() and len(core) > 1):
        return 0.4
    if len(core) == 1 and core.isalpha():
        return 0.3
    if "\n" in s or "\r" in s:
        return 0.25
    if core and not any(c.isalnum() for c in core):
        return 0.11
    if core.isalpha() and s.startswith(" "):
        return 0.085
    if core.isalpha():
        return 0.0
    return 0.07


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == BAR:
        return None, -1.75
    starts_segment = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_segment:
        return None, _segment_start_value(tok)
    return None, 0.0

programs.sol:
"""A spelling-pattern approximation for d/д clusters in Latin and Cyrillic.

Negative: d + z/j/zh (including дз/дж). Positive: d + v/w, the dwell
stem, and some Cyrillic дл-/дн- continuations. Responses are stronger
on short word pieces, with a small echo on the next continuation.
These are spelling rules, not a phonetic analysis or a word lookup table.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=131072)
def spelling(text):
    names = [unicodedata.name(c, '') for c in text if c.isalpha()]
    allowed = all('LATIN' in n or 'CYRILLIC' in n for n in names)
    return anyascii(text).lower(), any('CYRILLIC' in n for n in names), allowed


def response(previous, raw):
    s, cyr, allowed = spelling(raw)
    if not s or not allowed:
        return 0.001
    value = 0.001
    letters = sum(c.isalpha() for c in previous)
    alone = letters == 1
    single, long = len(raw) == 1, len(raw) > 3
    if previous.endswith('d') and not s[0].isspace():
        if s[0] in 'zj':
            if cyr:
                value -= 1.1 + 2.3 * alone + 4.9 * single
            elif s[0] == 'z':
                value += -4.8 + 1.6 * alone - 1.7 * single + 3.2 * long
            else:
                value += -1.7 + 1.3 * long
            value -= 3.0 * s.startswith('zh')
        elif s[0] in 'vw':
            if s.startswith('well'):                 # dwell and names in -dwell
                value += 4.7 + 5.0 * alone
            elif not long:
                value += (2.3 if letters <= 3 else 1.0) + 3.8 * (cyr and alone)
                if len(s) > 1 and not any(c in 'aeiouy' for c in s[1:]):
                    value -= 2.1
                value -= 1.4 * (single and raw.isupper())
        elif cyr and s[0] == 'l':
            value += 4.2 if alone and s.startswith('li') else 0.5  # длина: length
        elif cyr and s[0] == 'n':
            value += 1.3 if alone else 0.4
    word = s.lstrip()
    if word.startswith(('dv', 'dw')):
        value += -0.2 + 2.4 * cyr + 2.2 * (len(word) == 2)
    if word.startswith('dwell'):
        value += 4.8
    if word.startswith(('dz', 'dj')):
        value += -0.7 - 2.3 * cyr
    if s[0].isalpha():
        if previous.lstrip() in ('dv', 'dw'):
            value += 1.8 + 3.4 * cyr
        elif previous.lstrip() in ('dz', 'dzh', 'dj'):
            value -= 1.6
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    value = response(previous, raw)
    current = spelling(raw)[0]
    if previous.endswith('d') and current in ('v', 'w', 'z', 'zh', 'j'):
        current = 'd' + current
    return (doc, current), value

"""A detector for reserved words in source code and formal proofs.

Predict negative values for statement/declaration words, especially SQL pairs,
proof commands, assembly operations, and procedure/block syntax. Imports and
output commands are weaker. Token whitespace distinguishes many spellings;
logical line starts include numbered listings and JSON-escaped newlines.
A line-leading `private` is a small positive exception. Two formatting rules
cover a document-initial Title colon and doubled middle dots; otherwise the
prediction is zero.
The 600-character suffix is cleared at every document boundary.
"""
import re

READS = ()


def response(s, tail):
    w = s.strip()
    if s == ':' and tail == 'Title':
        return -1.5
    if s == '··':  # Repeated middle-dot formatting marks.
        return -0.6
    if not w or not w.isascii() or not w.isalpha():
        return 0.0
    line = re.split(r'\n|\\n', tail)[-1]
    start = not line.strip() or bool(re.fullmatch(r' *\d+[\t ]*', line))
    tab, bare = s.startswith('\t'), s == w
    previous = re.search(r'([A-Za-z]+)\s*$', tail)
    previous = previous[1].lower() if previous else ''

    # A few reserved words can finish in a separate token.
    if bare and not start and tail[-1:].isalpha():
        fragment = re.search(r'[A-Za-z]+$', line)
        word = (fragment[0] if fragment else '') + w
        if word in {'PROCEDURE', 'CURSOR'}:
            return -4.4
        if word.lower() in {'jnz', 'jz'}:
            return -2.6
        return -1.0 if word.lower() == 'echo' else 0.0

    # Multiword commands, including SQL schema declarations.
    if w == 'TO' and previous in {'go', 'goto'}:
        return -3.9
    if w.lower() == 'key' and previous in {'foreign', 'primary'}:
        return -2.7 if previous == 'foreign' else -1.9
    if w.lower() == 'table' and previous in {'create', 'alter', 'drop', 'truncate'}:
        return -2.6
    if w.lower() == 'into' and previous in {'insert', 'merge', 'replace'}:
        return -2.7
    if w == 'import' and previous == 'open':
        return -4.2
    if w in {'CREATE', 'ALTER', 'DROP', 'INSERT', 'UPDATE', 'DELETE'}:
        return -1.2
    if w in {'INTO', 'JOIN'}:
        return -1.6
    if w in {'FROM', 'WHERE', 'SELECT', 'HAVING', 'UNION'}:
        return -0.7
    if w == 'SET' and start:
        return -2.0
    if w in {'DO', 'IF'} and start:
        return -1.7
    if w in {'TABLE', 'KEY', 'CONSTRAINT', 'DEFAULT', 'REFERENCES'}:
        return -0.3

    # Proof-language context, not ordinary prose mentioning a proof.
    formal = any(t in tail for t in ('\\<', '⊢', '-- tactic'))
    formal |= bool(re.search(
        r'(?:^|\n|\\n)\s*(?:\d+\s+)?(?:theorem|lemma|proof)\b', tail))
    if bare and w == 'theorem':
        return -2.7
    if w in {'proof', 'assume', 'have', 'fix', 'obtain', 'show', 'thus', 'hence'}:
        if formal or (start and w in {'proof', 'assume'}):
            return -3.1
    if w in {'moreover', 'unfolding', 'using'} and formal:
        return -1.5
    if bare and start and w == 'definition':
        return -1.8
    if w == 'goal' and tail.rstrip().endswith('--'):
        return -2.0

    # Assembly and older block/procedure-oriented languages.
    if bare and start and tail:
        if w in {'mov', 'jmp'}:
            return -4.4
        if w == 'call':
            return -2.8
        if w in {'lw', 'sw', 'ret', 'inc', 'halt'}:
            return -1.0
    if start and w in {'begin', 'end', 'BEGIN', 'END'}:
        return -2.0 if w.lower() == 'begin' else -1.3
    if start and w == 'Dim':
        return -2.3
    if w in {'Sub', 'Function'} and previous in {'public', 'private', 'end'}:
        return -2.2
    if w == 'Each' and previous == 'for':
        return -1.7
    if start and w == 'procedure':
        return -3.9
    if start and (w == 'wire' or (bare and w in {'method', 'library'})):
        return -2.4
    if start and bare and w == 'case':
        return -1.4

    # Common imports, function definitions, output, and member declarations.
    if w in {'import', 'use', 'from'} and (tab or start):
        if tab:
            return -0.8 if w == 'from' else -1.5
        if w == 'from':
            return -0.6 if bare else -0.4
        return -0.9 if w == 'use' else -0.4
    if w == 'print' and bare and start:
        return -1.3 if '\\n' in tail[-10:] else -0.2
    if w == 'echo' and (start or tab):
        return -0.8
    if (w in {'fi', 'done'} and (start or tab)) or (w == 'then' and tab):
        return -1.3
    if w in {'function', 'func', 'def', 'fn', 'async'}:
        if tab:
            return -0.8
        if start:
            return -1.1 if w == 'function' else -0.4
        if bare or w in {'def', 'func', 'fn'}:
            return -0.3
    if w in {'using', 'package', 'namespace', 'typedef', 'struct', 'extern',
             'type', 'val', 'local', 'mod', 'pub'} and (start or tab):
        return -0.5
    if w == 'static' and (start or tab):
        return -0.4
    if w == 'private' and start:
        return 0.4
    if w in {'if', 'for'} and bare and start:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, tail)
    return (document, (tail + token)[-600:]), value

"""Approximate a response to web-page furniture, especially educational pages.

Negative pulses mark completion labels and periods terminating extracted titles;
positive pulses mark navigation labels. Unmatched text is zero, except for a
0.17 document-start default. This sparse approximation omits weak lexical
variation. Only a 500-character tail is carried, reset at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    s = prefix.token_strings[-1]
    line = tail.rsplit('\n', 1)[-1]
    value = 0.0

    # Standalone status and attribution fields, not the same words in prose.
    if s == 'olved' and line == 'S':
        value = -4.2 if re.search(r'ago\s+S$', tail) else -1.0
    elif s == ' recorded' and line == 'Comment':
        value = -4.6
    elif s == 'ed' and line == 'Award':
        value = -3.4
    elif s == 'Submitted' and not line.strip():
        value = -3.2
    elif s == ' on' and line == 'Submitted':
        value = -2.2
    elif s == ' offered' and line == 'Subjects':
        value = -0.8
    elif s == ' Presentation' and line.endswith('PPT'):
        value = -8.0

    # A title's final period is distinct from a normal sentence-ending period.
    elif s == '.':
        if re.search(r'^#+ Problem \d+$', line):
            value = -8.0
        elif line.lstrip().startswith('### '):
            value = -1.6
        elif line.lstrip().startswith('# '):
            value = -0.8
        else:
            words = re.findall(r'[A-Za-z]+', re.split(r'[.!?]', line)[-1])
            if words and len(words) <= 12:
                capitals = sum(w.istitle() or w.isupper() for w in words)
                if capitals >= 2 and capitals / len(words) >= 0.6:
                    value = -0.15
    elif s == '###' and tail.endswith('\n\n'):
        value = -0.2
        if re.search(r'\n### ', tail):
            value = -0.8

    # Navigation and search controls.
    elif s.lower() == ' menu':
        value = 0.12
        if re.search(r'(Context|Audience|administration|select)$', tail):
            value = 1.0
    elif s == ' navigation' and tail.endswith('Jump to:'):
        value = 1.5
    elif s == ' Views' and tail.endswith('·'):
        value = 0.8
    elif s == ' searches' and line == 'Related':
        value = 1.6
    elif s == '\n\n' and line in {'Related', 'Related searches', 'Related Articles'}:
        value = 0.9

    if position == 0 and value == 0.0:
        value = 0.17
    return (doc, (tail + s)[-500:], position + 1), value

"""Respond to conventional programming-name prefixes.

A PascalCase name after a one-letter framework prefix (Q for Qt, J for Swing,
T for ROOT/Delphi, F/U/S for Unreal-style types) gets a negative value.
Getters and setters get smaller responses depending on case and name style.
Other forms are near zero; document and row starts use a small positive baseline.
The carry tracks the current ASCII identifier, not merely the last token, so
letters inside longer words or encoded strings aren't mistaken for prefixes.
This keeps naming conventions, not individual names or their varying strengths.
"""
import re

READS = ()

# Rounded response means measured on training rows.
TYPE = {'Q': -5.1, 'T': -2.9, 'J': -1.7,
        'F': -3.3, 'U': -1.5, 'S': -0.25}
MERGED_TYPE = {'Q': -3.6, 'J': -1.2, 'F': -2.2}
ACCESSOR = {'get': 0.50, 'set': 0.32, 'Get': -0.29, 'Set': 0.02}


def category(identifier, token, first=False):
    if first:
        return 'start'
    if identifier in TYPE and re.match(r'[A-Z][a-z]', token):
        return 'class.' + identifier
    match = re.match(r'([^A-Za-z0-9_]*)([QTJFUS])[A-Z][a-z]', token)
    if match and (match[1] or not identifier):
        return 'merged.' + match[2]
    if identifier in ACCESSOR:
        if re.match(r'[A-Z]', token):
            return 'accessor.' + identifier
        if re.match(r'_[a-zA-Z]', token):
            return 'snake.' + identifier
        if re.match(r'[a-z]', token):
            return 'lower.' + identifier
    return 'other'


def next_identifier(identifier, token):
    match = re.search(r'[A-Za-z0-9_]+$', identifier + token)
    return match[0][-16:] if match else ''


VALUES = {
    'start': 0.06, 'other': 0.001,
    **{'class.' + k: v for k, v in TYPE.items()},
    **{'merged.' + k: v for k, v in MERGED_TYPE.items()},
    **{'accessor.' + k: v for k, v in ACCESSOR.items()},
    'snake.get': 0.09, 'snake.set': 0.19,
    'lower.get': -0.18, 'lower.Get': -0.12,
    'lower.set': 0.0, 'lower.Set': -0.06,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    identifier = '' if first else carry[1]
    value = VALUES.get(category(identifier, token, first), 0.0)
    return (document, next_identifier(identifier, token)), float(value)

"""Approximate the strong math/TeX spelling responses of this component.

It recognizes completed function names, accents, font changes, spacing and
TeX environment braces, even when their names span tokens.  Split function
names give a stronger response.  Separate small rules handle 'no one' and
repeated dot leaders.  Only a short text tail is kept, reset per document.
"""
import re

READS = ()
TRIG = frozenset(('sin', 'cos', 'tan', 'cot', 'sec', 'csc',
                  'sinh', 'cosh', 'tanh', 'coth', 'sech', 'csch',
                  'arcsin', 'arccos', 'arctan', 'arccot', 'arcsec', 'arccsc'))
ACCENTS = frozenset(('bar', 'hat', 'dot', 'ddot', 'tilde',
                     'widehat', 'widetilde'))
VECTOR_MARKS = frozenset(('vec', 'overrightarrow', 'overleftarrow'))


def tex_value(name):
    if name in ACCENTS or name in ('ensuremath', 'rule', 'ddots'):
        return 1.2
    if name in VECTOR_MARKS or name in ('phantom', 'hphantom', 'vphantom',
                                       'bm', 'pmb', 'mathop'):
        return 0.95
    if name in ('overline', 'underline', 'hspace', 'vspace', 'textup',
                'textnormal'):
        return 0.78
    if name in ('boldsymbol', 'textit', 'mathfrak'):
        return 1.1
    if name == 'mathcal':
        return 0.7
    if name in ('mathbf', 'textbf'):
        return 0.57
    if name in ('mathbb', 'mbox', 'newcommand', 'operatorname'):
        return 0.48
    if name in ('mathrm', 'rm'):
        return 0.2
    if name in ('hfill', 'vfill', 'centering'):
        return 0.55
    if name in ('frac', 'text'):
        return 0.12
    if name == 'dfrac':
        return 0.3
    if name in ('left', 'right', 'big'):
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = tail + token
    value = 0.0
    command = re.search(r'\\([A-Za-z]+)$', text)
    if command and token and token[-1].isalpha():
        value = tex_value(command[1])

    # Do not mistake the end of a longer word, or a Turkish suffix, for tan.
    match = re.search(r"(?<![^\W\d_])(?<!['’])([A-Za-z]+)$", text)
    if match and token and token[-1].isalpha():
        name = match[1]  # Mathematical names are conventionally lowercase.
        math_context = bool(re.search(
            r'[0-9=+*/^_$\\α-ωΑ-Ω]|\b(angle|derivative|equation|radian|'
            r'logarithm|logarithms|trigonometric|hyperbolic|triangle)\b',
            tail[-80:]))
        if name in TRIG:
            split = len(match[1]) > len(token.strip())
            if name in ('sec', 'sech') and not (command and command[1] == name):
                # 'sec' is usually a time unit or section, not secant.
                math_context = bool(re.search(
                    r'\b(angle|derivative|secant|trigonometric)\b', tail))
            if split and name not in ('sec', 'sech'):
                value = 1.08
            elif math_context:
                value = 0.65 if name in ('sin', 'cos') else 0.78
            else:
                value = 0.1 if name in ('sin', 'cos', 'tan') else 0.0
        elif name in ('ln', 'lg'):
            value = 0.45
        elif name in ('log', 'exp', 'floor', 'ceil'):
            # Separate mathematical functions from log files and console.log.
            api = bool(re.search(r'\b(np|numpy|math)(?:\.)?$', tail))
            tex = bool(command and command[1] == name)
            expression = bool(re.search(r'[0-9=+*^_($α-ω]$', tail.rstrip()))
            subject = bool(re.search(r'\b(logarithm|logarithms|complexity)\b', tail))
            if api or tex or (token.strip() == name and (expression or subject)):
                value = 0.55 if name == 'log' else 0.45

    if token == '{':
        if re.search(r'\\begin$', tail):
            value = 1.23
        elif re.search(r'\\end$', tail):
            value = 0.82
        elif re.search(r'\\[hv]space$', tail):
            value = 0.35
        elif re.search(r'\\mathrm$', tail):
            value = -0.2
    if token.strip() == 'one' and re.search(r'\b[Nn]o$', tail.rstrip()):
        value = 0.52
    if token == ' .' and re.search(r'(?: \.){3}$', tail):
        value = 0.4
    if token and set(token) == {'·'} and tail.endswith('·'):
        value = -1.0
    return (doc, text[-100:]), value

"""Predict DAT-like spelling responses, not a general notion of information.

Complete date/data-family tokens get modest positive values; DAT fragments
and AT continuing a preceding D get larger ones, especially in Cyrillic.
Transliteration also covers accented letters. English suffixes, CamelCase
boundaries and a few other DA continuations receive smaller or negative
values. Chinese and Japanese words for data have their own modest values.
Uses nearby tokens only, resetting its state at document boundaries.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()


@lru_cache(maxsize=65536)
def spelling(text):
    return anyascii(text).lower()


@lru_cache(maxsize=131072)
def response(token, previous):
    s = spelling(token)
    word = s.lstrip(' \t\r\n_./\\-($@:\"\'')
    if token in ('数据', 'データ'):
        return 0.45 if token == '数据' else 1.7
    if word.startswith('dat'):
        if word in ('data', 'datas', 'datos'):
            if s.startswith(('/', '-', '\\')):
                return 1.4
            if word.isalpha() and token.strip().isupper():
                return 1.45
            return 0.6 if token[:1].isspace() else 0.85
        if word in ('date', 'dates', 'dated', 'dating'):
            if word == 'dated':
                return 0.95
            if token.startswith('.D'):
                return 4.0
            return 1.65
        if word == 'dat':
            if token[:1].isspace() and token.strip().islower():
                return 1.8
            return 5.8
        if word == 'datum':
            return 5.8 if token.strip()[:1].isupper() else 2.5
        if word == 'daten':
            return 2.1
        if word == 'dato':
            return 1.6
        if word.startswith('datetime'):
            return 0.55
        return 0.15

    p = spelling(previous)
    if not p.endswith('d') or not s or not s[0].isalpha():
        return 0.0
    # CamelCase starts a new word rather than continuing the final D.
    if token[:1].isupper() and not token.isupper():
        return 0.0
    # No whitespace may intervene: this is a within-word continuation.
    if s.startswith('at'):
        if s.startswith(('atabase', 'ataset')):
            return 0.2
        if regex.match(r'\p{Script=Cyrillic}', token):
            if s.startswith('atsi'):
                return 4.5 if s == 'atsi' else 1.6
            if s.startswith('atel'):
                return 4.2
            if s.startswith("at'"):
                return 1.0
            return 8.7 if s == 'at' else 7.5
        if s.startswith('ation'):
            return 0.7 if len(p.strip()) <= 3 else 0.0
        if s in ('ate', 'ated', 'ates', 'ating', 'ative'):
            return 4.5 if len(p.strip()) <= 3 else 0.3
        return 4.8 if len(p.strip()) <= 7 else 0.0
    if s.startswith(('ar', 'anc', 'andy')):
        return -1.3
    if s.startswith('a') and len(s) > 1:
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    # Recover a preceding D split across UTF-8 byte tokens.
    if '\ufffd' in previous and prefix.position >= 2:
        if prefix.document_ids[-3] == doc:
            previous = b''.join(prefix.token_bytes[-3:-1]).decode(
                'utf-8', errors='ignore'
            )
    return (doc, token), response(token, previous)

"""A sparse lexical/typographic approximation, not one semantic topic.

Negative cues are the Chinese tin character 锡/錫 (also in short compounds),
cooking-pot forms, and the characters 舔 (lick), 肥 (fat), and 葱 (scallion).
The paving/shop character 铺 and its variants are positive. Separate rules
recognize selected split Unicode glyphs and damaged or doubled punctuation.
Document-initial English greetings are negative; an inverted question mark is
positive. UTF-8 fragments are buffered and state resets between documents.
Other text stays near zero: remaining context-dependent variation is omitted.
"""
import codecs
import unicodedata
from functools import lru_cache
from opencc import OpenCC

READS = ()
_converter = OpenCC('t2s')


@lru_cache(maxsize=4096)
def simplify(word):
    return _converter.convert(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    pending, recent = (b'', '') if start else carry[1:]
    partial = bool(pending)
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    word = text.strip()
    plain = simplify(word) if not word.isascii() else word
    value = -0.002

    if start:
        if word.lower() in {'hi', 'hello', 'hey'}:
            value = -1.8
        elif word == '¿':
            value = 1.65
    elif plain.endswith('锡') and len(plain) <= 2:
        value = -2.0 if len(plain) == 2 else -(7.5 if partial else 5.8)
    elif plain == '锅':
        value = -5.4 if partial or word != plain else -3.7
    elif plain in {'火锅', '锅炉'}:
        value = -1.6
    elif plain.startswith('铺') and len(plain) <= 2:
        value = 4.2 if len(plain) == 1 else 2.1
    elif word in {'舖', '舗'}:  # other shop/paving character forms
        value = 3.7 if word == '舖' else 1.1
    elif word in {'舔', '肥', '葱'}:
        value = -0.9
    elif partial and word == 'ち':  # split Japanese chi syllable
        value = -2.85
    elif word == '\u200d':  # emoji's zero-width joiner
        value = -1.3
    elif partial and word == '\u2061' and recent.endswith(' '):
        value = -0.7  # invisible mathematical function-application sign
    elif partial and len(word) == 1 and unicodedata.name(
        word, '').startswith('COMBINING'):
        value = -0.3
    elif word in {'\x96', '\x97'}:
        value = 1.6  # legacy dashes misread as control characters
    elif recent.endswith('\x80') and word in {'\x93', '\x94'}:
        value = 1.4  # doubly misdecoded dash
    elif recent.endswith('â') and text in {'€“', '€”'}:
        value = 1.2  # mojibake of a typographic dash
    elif (recent + text).endswith('â€¦'):
        value = 0.7  # mojibake of an ellipsis
    elif (recent + text).endswith('Ä™'):
        value = -1.3  # mojibake of Polish e-with-ogonek
    elif text == '··':
        value = 0.465
    elif text == '.,':
        value = 0.115
    elif text == "'\"" or (text in {'”', '″'} and recent.endswith(('’', '′'))):
        value = 0.85  # juxtaposed closing quotation marks

    return (doc, data[used:], (recent + text)[-8:]), value
